      world: v7Freeze(v7CanonicalNumbers(next)),
      outcomes,
      paused: null,
    };
  } catch (error) {
    if (error instanceof V7ComputePause)
      return { world: savedWorld, outcomes: {}, paused: error.message };
    throw error;
  }
}

