}
export function v7Cursor(plan: V7Plan, tick: number): V7Cursor {
  return {
    plan: v7Clone(plan),
    step: 0,
    repetition: 0,
    cycle: 0,
    startedAt: tick,
    navigation: null,
    reason: null,
  };
}
function advance(cursor: V7Cursor): void {
  cursor.repetition += 1;
  if (cursor.repetition >= (cursor.plan.steps[cursor.step]?.repeat ?? 1)) {
    cursor.step += 1;
    cursor.repetition = 0;
  }
  if (cursor.step >= cursor.plan.steps.length) {
