          continue;
        if (!source) {
          source = {
            source: rule.id,
            value: 0,
            lastEvent: '',
            lastTick: -1,
            expires: 0,
            exposures: 0,
          };
          actor.wellbeing.sources.push(source);
        }
        const amplitude =
          rule.repeatWindow &&
          world.tick - lastReward <= rule.repeatWindow.rounds
            ? rule.repeatWindow.amount
            : rule.repetition === 'diminish'
              ? rule.amount / (1 + source.exposures * 0.15)
              : rule.amount;
