      effects.set(actor.id, {
        stacks: data.stacks.map((s) =>
          s.id === stack.id ? { ...s, owner: actor.id, position: null } : s,
        ),
        sites: data.sites,
        vital: v,
        memory,
        writes: [`stack:${stack.id}`],
        detail: `Collected ${String(stack.quantity)} units; pickup alone does not nourish.`,
      });
