        const effect = executeEvolution(world, actor, mechanic, a.args);
        effects.set(actor.id, effect);
        log('used', effect.detail, skill.id);
      } catch (error) {
        log(
          'use-failed',
          error instanceof Error ? error.message : 'Execution failed.',
          skill.id,
        );
      }
