import type {
  V7Actor,
  V7Object,
  V7Point,
  V7Spatial,
  V7World,
} from './continuous-types.js';
import {
  v7Distance,
  v7Inside,
  v7Local,
  v7Obstacles,
  v7SegmentClear,
  v7ShapesOverlap,
} from './continuous-geometry.js';
export const canopyPoint = (s: V7Spatial, x: number, y: number): V7Point => ({
  x: s.x + x * Math.cos(s.angle) - y * Math.sin(s.angle),
  y: s.y + x * Math.sin(s.angle) + y * Math.cos(s.angle),
