  [-1, 1].flatMap((x) =>
    [-1, 1].map((y) => ({
      ...canopyPoint(s, x, y),
      angle: 0,
      shape: { kind: 'circle' as const, radius: 0.08 },
      solid: true,
      interaction: 0.65,
      entrances: [],
