    .filter((o) => o.kind === 'rain-canopy' && Number(o.data.condition) > 0)
    .filter((o) => {
      const q = v7Local(p, o.spatial);
      return (
        Math.abs(q.x) + radius <= 1 + 1e-8 && Math.abs(q.y) + radius <= 1 + 1e-8
