                w.state.willowMaterials === 1
                  ? j.inputs.reduce(
                      (n, i) =>
                        n +
                        Number(i.moisture) *
                          Number(i.mass) *
                          Number(i.quantity),
                      0,
                    ) / 2.2
                  : (forestClimate(w, a.position).rain ?? 0),
              lastTick: -1,
              inputs: j.inputs,
              repairs: [],
