    if (!old) continue;
    const prior = v7Observe(before, actor.id),
      current = v7Observe(world, actor.id);
    for (const other of current.actors.filter(
      (a) => !prior.actors.some((p) => p.id === a.id),
    ))
      forestEvent(
        world,
        'actor-seen',
        `${actor.name} now sees ${other.name}.`,
        actor.position,
        actor.id,
        { observedActor: other.id },
        other.id,
      );
