      actor.memory.discoveries ?? {},
    ))
      if (!old.memory.discoveries?.[resource])
        forestEvent(
          world,
          'discovered',
          `Observed properties of ${resource} through actual use.`,
          actor.position,
          actor.id,
          { resource, observed: knowledge },
          resource,
        );
