      tick: w.tick,
      before: j.before,
      afterExposure: beforeHealing,
      after: { ...a.vitals },
      energyCost: j.lastTick === w.tick ? 0.5 : 0,
      satietyCost: j.lastTick === w.tick ? 0.2 : 0,
      recoveredEnergy: j.lastTick === w.tick ? j.recovered : 0,
      injury,
      healing,
      remaining: j.remaining,
      cumulativeHealing: j.healed,
    };
