        ...v7Clone(j),
        status: 'completed',
        tick: w.tick,
      };
      delete a.extensionState['recuperation:pending'];
      forestClearOperation(a);
      const outcome = outcomes[a.id];
      if (outcome) outcome.complete = true;
    }
  }
