  tool: string;
  sample: string;
  reserved: number;
  removed: number;
  stage: number;
  paid: number;
  x: number;
  y: number;
}
const key = 'open:bark-work';
const job = (a: V7Actor) => a.extensionState[key] as BarkWork | undefined;
function reachable(c: V7ActionContext, id: string) {
  const s = barkSubstrate(c.world, id);
