      ...scratchStroke(w, first, second, j.id, j.stage < 2 ? 0.5 : 1),
      stage: j.stage + 1,
      dwell: 1,
      forceLevel: j.stage < 2 ? 'lower actuator level' : 'upper actuator level',
      measurementStatus:
        'achieved model quantities, independently uncalibrated',
