      : 'Executed one bounded contact using an existing physical tip; no calibrated standard was supplied.',
    {
      project: j.id,
      stage: j.stage,
      remainingWork: 6 - j.stage,
      paidEnergy: j.paid,
      specimens: j.specimens,
