      foodUnitMass(w, s) * s.quantity >= 0.005 &&
      !old.fractured &&
      (w.resources.find((r) => r.id === s.resource)?.properties?.hardness ??
        0) >= 1;
    return old;
  }
  const r = w.resources.find((r) => r.id === s.resource);
  if (!r) throw new Error('Missing actual material');
