  w.stacks.push({
    id,
    resource: 'scratch-debris',
    quantity: 0.1,
    quantityTenths: 1,
    owner: s.owner,
    position: { ...s.position },
    origin: s.origin,
    physical: { unitMass: 0.001, unitWater: 0, unitSolids: 0.001 },
    processing: {
      scratchDebris: {
        project,
        source: s.id,
