    .filter((o) => o.kind === 'open-refuge')
    .map((o) => ({
      o,
      sun: refugeRay(
        o,
        a.position,
        Math.cos(sunAngle) * 0.5,
        Math.sin(sunAngle) * 0.5,
      ),
      rain: refugeRay(o, a.position, wind * 0.25, 0),
      overhead: refugeRay(o, a.position, 0, 0),
    }))
    .filter((r) => r.overhead > 0);
