    blockedSolar = solar * 0.65 * best.sun,
    rainAvoided = rain * 0.4 * best.rain,
    windAvoided = wind * Math.min(0.2, best.overhead * 0.1),
    trappedHeat = Math.max(0, climate.temperature - 28) * windAvoided * 0.2;
