    plainWet = Math.max(
      0,
      Math.min(1, oldWet + rain * 0.025 - climate.daylight * 0.01),
    ),
    wet = Math.max(
      0,
      Math.min(
        1,
        oldWet + (rain - rainAvoided) * 0.025 - climate.daylight * 0.01,
      ),
    );
