    target: best.o.id,
    sunCoverage: best.sun,
    rainCoverage: best.rain,
    windAvoided,
    blockedSolar,
    rainAvoided,
    trappedHeat,
    ambient,
    plainTemperature: plain,
    temperature: protectedTemperature,
