    w.processes = w.processes.filter((x) => x.id !== p.id);
    return;
  }
  p.next = w.tick + 1;
  if (j.mode !== 'assemble') {
    const sample = w.stacks.find((s) => s.id === j.specimen);
    if (sample && j.mode === 'test-vine') {
      evaporate(
        w,
        sample,
        sample.owner
          ? (w.actors.find((a) => a.id === sample.owner)?.position ??
              sample.position)
