        ...s,
        id: v7Id(w, 'item'),
        owner: null,
        position: { x: j.x, y: j.y },
        processing: {
          ...(s.processing ?? {}),
          wovenDamage: {
            project: j.id,
            broken: true,
            reason:
              'structural destruction; conserved salvage, not pristine input',
          },
        },
      };
