    w,
    'woven-support-stopped',
    'Active work paused; consumed components remain real and surviving unconsumed allocations are released once. Resume names this exact work record.',
    a.position,
    a.id,
    {
      project: j.id,
      stage: j.stage,
      remainingWork: j.total - j.stage,
