    for (
      let x = Math.max(0, actor.position.x - 5);
      x <= Math.min(world.settings.width - 1, actor.position.x + 5);
      x++
    )
      if (visible({ x, y }))
        terrain.push({ x, y, biome: cBiomeAt(data, { x, y }) });
