}
.event-active {
  animation: event-emphasis 0.7s ease-out;
}
.event-rest,
.event-eat {
  animation: actor-emphasis 0.7s ease-out;
}
@keyframes event-emphasis {
  from {
    opacity: 0.35;
  }
  to {
    opacity: 1;
  }
}
@keyframes actor-emphasis {
  50% {
    filter: brightness(1.25);
  }
}
@media (max-width: 1050px) {
  .obs-layout {
    grid-template-columns: minmax(380px, 1fr) 285px;
    padding: 16px;
  }
  .obs-header {
    padding: 18px;
  }
  .header-controls a {
    display: none;
  }
  .observer-card {
    padding: 15px;
  }
  .event-list {
    grid-template-columns: 1fr 1fr;
  }
}
@media (max-width: 750px) {
  .obs-layout {
    display: block;
  }
  .obs-aside {
    margin-top: 18px;
    display: grid;
    grid-template-columns: 1fr 1fr;
  }
  .world-toolbar {
    flex-wrap: wrap;
  }
  .obs-header {
    height: auto;
    gap: 10px;
    align-items: flex-start;
  }
  .header-controls {
    flex-direction: column;
  }
  .brand h1 {
    font-size: 19px;
  }
  .brand-mark {
    display: none;
  }
  .world-stage {
    height: 65vh;
    min-height: 420px;
  }
  .event-list {
    grid-template-columns: 1fr;
  }
  .observer-card {
    min-width: 0;
  }
  .minimap {
    width: 105px;
    height: 105px;
  }
  .camera-tools {
    top: 50px;
  }
  .stage-caption {
    max-width: 60%;
  }
}
@media (prefers-reduced-motion: reduce) {
  * {
    animation: none !important;
  }
}

.camera-tools button[aria-pressed='true'] {
  background: #315b45;
  color: #fff5dd;
}
@media (max-width: 750px) {
  .playback {
    flex-wrap: wrap;
  }
  .playback input {
    order: 2;
    flex-basis: 100%;
  }
  .round-value {
    min-width: 0;
    flex: 1;
    text-align: center;
  }
  .obs-aside {
    grid-template-columns: 1fr;
  }
  .header-controls select {
    max-width: 140px;
  }
  .brand {
    min-width: 0;
  }
  .brand h1 {
    font-size: 18px;
  }
  .brand p {
    font-size: 10px;
  }
}

.scene-object,
.scene-actor {
