.scene-object:focus-visible,
.scene-actor:focus-visible {
  filter: brightness(1.3) drop-shadow(0 0 0.08px #fff4c6);
}

.inventory-heading {
  margin-top: 18px;
}
.carried-items {
  margin-top: 8px;
  font-size: 12px;
  color: #60725e;
  line-height: 1.6;
}
details summary {
  font-size: 11px;
  color: #6d7e65;
