  min-width: 0;
}
.panel {
  background: #fdfef9;
  border: 1px solid #e0e6da;
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 3px 8px #263f3703;
}
.panel-heading {
  padding: 22px 24px 18px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
}
h2 {
  font-size: 16px;
  font-weight: 650;
  margin-top: 5px;
}
h3 {
  font-size: 12px;
  font-weight: 650;
}
.mono {
  font-family: 'SFMono-Regular', Consolas, 'Liberation Mono', monospace;
}
#world-size {
  font-size: 11px;
  margin-left: 10px;
  color: #9aa38f;
  font-weight: 400;
}
.view-switch {
  display: flex;
  padding: 3px;
  background: #edf0e8;
  border-radius: 6px;
  gap: 2px;
}
.view-switch button {
  border: 0;
  background: transparent;
  border-radius: 4px;
  color: #879281;
  font-size: 11px;
  padding: 7px 11px;
}
.view-switch button[aria-pressed='true'] {
  background: #fcfdf9;
  color: #304e3b;
  box-shadow: 0 1px 4px #34482d15;
}
.map-stats {
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 12px 24px;
  font-size: 10px;
  color: #778672;
  border-top: 1px solid var(--line);
}
.map-stats > :last-child {
  margin-left: auto;
  font-size: 10px;
  letter-spacing: 1px;
}
.map-stats b {
  margin-left: 5px;
  color: #365445;
}
.status-dot {
  display: inline-block;
  height: 5px;
  width: 5px;
  border-radius: 50%;
  background: #7fa782;
  margin-right: 7px;
  vertical-align: 2px;
}
.map-surround {
  background: #193b32;
  padding: 15px 19px 15px 12px;
}
.x-axis {
  margin-left: 22px;
  display: grid;
  color: #719085;
  font:
    9px ui-monospace,
    monospace;
  height: 20px;
  text-align: center;
}
.map-row {
  display: flex;
}
.y-axis {
  width: 22px;
  flex-shrink: 0;
  display: grid;
  text-align: center;
  color: #719085;
  font:
    9px ui-monospace,
    monospace;
}
.y-axis span {
  align-self: center;
}
.world-grid {
  flex: 1;
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(var(--columns), minmax(0, 1fr));
  aspect-ratio: var(--columns) / var(--rows);
  border: 1px solid #496b584f;
  border-right: 0;
  border-bottom: 0;
}
.cell {
  position: relative;
  min-width: 0;
  min-height: 0;
  display: grid;
  place-items: center;
  border-right: 1px solid #65857522;
  border-bottom: 1px solid #65857522;
  background: #204639;
}
.cell:nth-child(3n) {
  background: #234a3c;
}
.cell.textured::before {
  content: '·';
  color: #44664b;
  position: absolute;
  font-size: 18px;
}
.cell.visible {
  background: #3b5b42;
  border-color: #b0bd762c;
}
.cell.visible:nth-child(3n) {
  background: #405e43;
}
.cell.fog,
.cell.fog:nth-child(3n) {
  background: #15362e;
  border-color: #6283720e;
}
.cell.fog::before {
  content: '';
}
.agent-token {
  padding: 0;
  border: 0;
  border-radius: 30%;
  width: 88%;
  aspect-ratio: 1;
  z-index: 2;
  background: transparent;
  filter: drop-shadow(0 1px 1px #0b282a90);
}
.agent-token.selected {
  outline: 1px solid #f3d997;
  outline-offset: 1px;
  background: #f5dc8c1c;
}
.agent-token svg,
.item-token svg {
  display: block;
  width: 100%;
  height: 100%;
}
.item-token {
  width: 70%;
  aspect-ratio: 1;
  position: absolute;
  filter: drop-shadow(0 1px 2px #102b3280);
}
.cell:has(.agent-token) .item-token {
  top: 0;
  right: 0;
  width: 43%;
  z-index: 3;
}
.item-count {
  position: absolute;
  right: -2px;
  bottom: 0;
  color: white;
  font-size: 9px;
}
.inventory-item {
  display: inline-flex;
  gap: 5px;
  align-items: center;
}
.inventory-item svg {
  width: 22px;
  height: 22px;
  flex-shrink: 0;
}
#current-event,
.event-description {
  white-space: pre-line;
}
.map-caption {
  margin-left: 22px;
  padding-top: 13px;
  font-size: 9px;
  color: #8ea798;
  display: flex;
  justify-content: space-between;
  gap: 8px;
}
.map-legend {
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 13px 24px;
  color: #82917c;
  font-size: 10px;
  border-bottom: 1px solid var(--line);
}
.map-legend i {
  display: inline-block;
  width: 7px;
  height: 7px;
  margin-right: 4px;
}
.legend-agent {
  background: #d1b589;
  border-radius: 50%;
}
.legend-item {
  background: #b6b783;
  transform: rotate(45deg);
  width: 5px !important;
  height: 5px !important;
}
.legend-vision {
  border: 1px solid #a3ac83;
  background: #e2e6ce;
}
.map-tip {
  margin-left: auto;
  color: #a2aa9a;
  font-size: 9px;
}
.replay-panel {
  padding: 23px 24px 20px;
  background: #f9fbf5;
}
.replay-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.replay-title h3 {
  margin-top: 5px;
  font-size: 14px;
}
#history-count {
  font-size: 11px;
  color: #688270;
  letter-spacing: 1px;
}
#timeline {
  display: block;
  width: 100%;
  height: 4px;
  border-radius: 2px;
  appearance: none;
  background: linear-gradient(
    to right,
    #698f6e var(--progress),
    #e1e7d9 var(--progress)
  );
  margin: 25px 0 20px;
  cursor: pointer;
}
#timeline::-webkit-slider-thumb {
  appearance: none;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #547d5c;
  border: 2px solid #fafcf3;
  box-shadow: 0 0 0 1px #547d5c;
}
#timeline::-moz-range-thumb {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: #547d5c;
  border: 2px solid #fafcf3;
}
.playback-controls,
.transport,
.playback-options {
  display: flex;
  align-items: center;
  gap: 7px;
}
.playback-controls {
  justify-content: space-between;
}
.icon-button {
  border: none;
  background: transparent;
  min-width: 29px;
  height: 31px;
  color: #87997d;
  font-size: 20px;
}
#first-frame {
  font-size: 12px;
}
.button.play {
  background: #335a43;
  border-color: #335a43;
  color: #fcfcf0;
  padding: 9px 20px;
  font-size: 11px;
}
#speed {
  border: 0;
  color: #71876d;
  background: transparent;
  font-size: 11px;
  padding: 6px;
}
.current-event {
  margin-top: 15px;
  padding-top: 13px;
  border-top: 1px solid #e7ecdf;
  font-size: 12px;
  color: #657a5d;
  line-height: 1.7;
}
.small-label {
  font-size: 9px;
  color: #7e947c;
  padding: 4px 6px;
  background: #edf2e8;
  border-radius: 3px;
  white-space: nowrap;
}
.agent-panel .panel-heading,
.skills-panel .panel-heading {
  padding: 22px 21px 17px;
}
.agent-select {
  display: block;
  width: calc(100% - 42px);
  margin: 0 21px;
  padding: 13px 11px;
  border: 1px solid #dce5d5;
  border-radius: 6px;
  color: #3f5b42;
  background: #f7f9f1;
  font-size: 12px;
}
.agent-meta {
  margin: 20px 21px 0;
  padding-bottom: 19px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  border-bottom: 1px solid var(--line);
}
.agent-meta span {
  font-size: 10px;
  color: #8c9a86;
  display: block;
  margin-bottom: 7px;
}
.agent-meta strong {
  font-size: 15px;
  color: #4e6851;
  font-weight: 500;
}
.inspector-block {
  margin: 20px 21px;
}
.inspector-block h3 {
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: #52664c;
  font-size: 11px;
}
#inventory-count {
  font-size: 10px;
  color: #8e9c81;
  font-weight: 400;
}
.chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 10px;
}
.inventory-item {
  color: #827447;
  border: 1px solid #e6e0c7;
  border-radius: 4px;
  background: #f8f5e6;
  padding: 6px 10px;
  font-size: 10px;
}
.empty-note,
.muted {
  font-size: 10px;
  color: #92a08a;
  line-height: 1.9;
}
.auto-label {
  color: #a7b09a;
  font-size: 9px;
  font-weight: 400;
}
.muted {
  margin: 10px 0 6px;
}
.visible-entities {
  display: flex;
  flex-wrap: wrap;
  gap: 7px 10px;
  font-size: 11px;
  line-height: 1.6;
  color: #6e7e65;
}
.seen-agent {
  color: #688773;
}
.skills-panel {
  padding-bottom: 9px;
}
.action-hint {
  font-size: 11px;
  color: #6e7e65;
  line-height: 1.8;
  background: #f2f5eb;
  padding: 10px 13px;
  margin: 0 21px 19px;
  border-left: 2px solid #becbae;
}
fieldset {
  border: 0;
  margin: 0;
  padding: 0 21px 8px;
  min-width: 0;
}
.skill-heading {
  display: flex;
  gap: 10px;
  align-items: flex-start;
}
.skill-number {
  font:
    9px ui-monospace,
    monospace;
  color: #9aa98b;
  border: 1px solid #e3e9d9;
  padding: 4px 5px;
  border-radius: 3px;
}
.skill-heading h3 {
  font-size: 12px;
}
.skill-heading p {
  font-size: 11px;
  margin-top: 5px;
  color: #6e7e65;
  line-height: 1.6;
}
.key-hint {
  margin-left: auto;
  flex-shrink: 0;
  white-space: nowrap;
  font:
    8px ui-monospace,
    monospace;
  color: #acb49f;
  padding-top: 5px;
}
.move-pad {
  display: grid;
  grid-template-areas: '. north .' 'west center east' '. south .';
  grid-template-columns: repeat(3, 36px);
  grid-template-rows: repeat(3, 31px);
  gap: 5px;
  justify-content: center;
  padding: 15px 0 0;
}
.move-pad button {
  background: #f2f5eb;
  border: 1px solid #dde6d3;
  border-radius: 5px;
  color: #6c8460;
  font-size: 16px;
}
.move-pad .north {
  grid-area: north;
}
.move-pad .south {
  grid-area: south;
}
.move-pad .east {
  grid-area: east;
}
.move-pad .west {
  grid-area: west;
}
.move-center {
  grid-area: center;
  display: grid;
  place-items: center;
  color: #a7b49a;
  font-size: 12px;
}
.skill-divider {
  height: 1px;
  background: var(--line);
  margin: 19px 0;
}
.empty-pickup {
  font-size: 11px;
  color: #6e7e65;
  background: #f8faf3;
  border: 1px dashed #e3e9d8;
  padding: 10px;
  border-radius: 4px;
  margin-top: 13px;
  text-align: center;
}
.pickup-button {
  font-size: 11px;
  background: #e9f0e2;
  color: #526d43;
  border: 1px solid #d4e1c9;
  width: 100%;
  margin-top: 12px;
  border-radius: 5px;
  padding: 10px;
}
.activity-panel .panel-heading {
  padding-bottom: 9px;
}
.activity-note {
  font-size: 11px;
  color: #6e7e65;
  padding: 0 24px 17px;
}
.event-row {
  width: 100%;
  border: 0;
  background: transparent;
  border-top: 1px solid #edf0e6;
  padding: 14px 24px;
  display: flex;
  align-items: center;
  text-align: left;
  gap: 17px;
}
.event-tick {
  color: #a5b099;
  font-size: 10px;
}
.event-description {
  color: #657a5d;
  font-size: 12px;
  line-height: 1.7;
}
.event-row.unsupported .event-description {
  color: #ad8e60;
}
.event-arrow {
  margin-left: auto;
  color: #afb99f;
  font-size: 11px;
}
.empty-events {
  font-size: 12px;
  color: #91a184;
  padding: 20px 24px 30px;
}
.footer {
  padding: 26px 0 32px;
  color: #a5ae99;
  font-size: 9px;
  letter-spacing: 0.6px;
  display: flex;
  justify-content: space-between;
  gap: 15px;
}
.footer-dot {
  margin: 0 8px;
  color: #c4ccbb;
}
.notice {
  position: fixed;
  bottom: 22px;
  left: 50%;
  transform: translateX(-50%);
  width: max-content;
  max-width: calc(100vw - 32px);
  background: #264d3e;
  color: #f4f6e7;
  padding: 13px 20px;
  border: 1px solid #62785b;
  border-radius: 8px;
  font-size: 12px;
  box-shadow: 0 6px 25px #10251a28;
  z-index: 10;
  line-height: 1.7;
}
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
@media (min-width: 1550px) {
  .world-grid {
    max-height: 610px;
  }
}
@media (max-width: 1050px) {
  .workspace {
    padding: 28px 24px 0;
  }
  .topbar {
    padding: 0 24px;
  }
  .main-layout {
    grid-template-columns: minmax(0, 1fr) 285px;
    gap: 16px;
  }
  .edition {
    display: none;
  }
  .session-actions {
    gap: 10px;
  }
  .rule-badge {
    display: none;
  }
  .panel-heading {
    padding: 18px 18px 16px;
  }
  .map-legend {
    gap: 12px;
    padding: 12px 18px;
  }
  .map-tip {
    display: none;
  }
}
@media (max-width: 780px) {
  .topbar {
    height: 65px;
    padding: 0 18px;
  }
  .brand {
    font-size: 9px;
    letter-spacing: 0.8px;
  }
  .brand-symbol {
    width: 27px;
    height: 27px;
    font-size: 22px;
  }
  .header-actions {
    gap: 0;
  }
  .header-actions .button {
    font-size: 10px;
    padding: 9px 6px;
  }
  .workspace {
    padding: 24px 16px 0;
  }
  .main-layout {
    grid-template-columns: 1fr;
  }
  .inspector {
    grid-template-columns: 1fr 1fr;
    align-items: start;
    gap: 16px;
  }
  .page-heading {
    margin-bottom: 24px;
  }
  .page-heading .eyebrow {
    font-size: 8px;
    letter-spacing: 1px;
  }
  h1 {
    font-size: 28px;
  }
  .subtitle {
    font-size: 11px;
  }
  .agent-token {
    font-size: 12px;
  }
  .panel-heading {
    padding: 18px;
  }
  .rule-badge {
    display: none;
  }
  .footer {
    flex-wrap: wrap;
  }
}
@media (max-width: 480px) {
  .inspector {
    grid-template-columns: 1fr;
  }
  .topbar {
    padding: 0 12px;
  }
  .brand {
    gap: 7px;
  }
  .brand b {
    display: block;
    margin-top: 3px;
  }
  .page-heading {
    align-items: flex-end;
  }
  .session-actions .button {
    font-size: 10px;
    padding: 8px 9px;
  }
  .page-heading .eyebrow {
    max-width: 210px;
    font-size: 7px;
  }
  .panel-heading {
    padding: 17px 14px;
  }
  .panel-heading h2 {
    font-size: 14px;
  }
  .view-switch button {
    padding: 6px 7px;
    font-size: 10px;
  }
  #world-size {
    font-size: 9px;
    margin-left: 5px;
  }
  .map-stats {
    padding: 11px 14px;
    gap: 10px;
    font-size: 9px;
  }
  .map-surround {
    padding: 10px 8px 12px 4px;
  }
  .map-caption {
    font-size: 8px;
  }
  .agent-token {
    font-size: 8px;
  }
  .agent-token.selected {
    outline-offset: 2px;
  }
  .map-legend {
    padding: 12px 14px;
    gap: 15px;
    font-size: 9px;
  }
  .replay-panel {
    padding: 20px 14px 16px;
  }
  .playback-controls {
    gap: 0;
  }
  .playback-options {
    gap: 0;
  }
  .playback-options .button {
    padding: 8px 5px;
    font-size: 10px;
  }
  .button.play {
    padding: 9px 13px;
  }
  .transport {
    gap: 1px;
  }
  .activity-note {
    padding: 0 14px 14px;
  }
  .event-row {
    padding: 12px 14px;
    gap: 11px;
  }
}
@media (prefers-reduced-motion: reduce) {
  button {
    transition: none;
  }
}

.history-storage-note {
  margin-top: 8px;
  color: #7d8c70;
  font-size: 10px;
  line-height: 1.8;
}
/* Survival history is observational; programs are displayed as text only. */
.survival-panel {
  padding: 24px;
}
.vital-signs {
  display: grid;
  gap: 12px;
}
.vital {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 6px;
  font-size: 12px;
}
.vital-meter {
  grid-column: 1 / -1;
  width: 100%;
  height: 10px;
  accent-color: #3d7654;
}
.vital-cold .vital-meter {
  accent-color: #468ba1;
}
.vital-heat .vital-meter {
  accent-color: #c37944;
}
.program-code {
  padding: 12px;
  border-radius: 6px;
  background: #183d32;
  color: #e8eddd;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  font-size: 12px;
  line-height: 1.7;
}
.learning-record {
  font-size: 12px;
  line-height: 1.6;
  border-left: 2px solid #b18c52;
  padding-left: 10px;
  overflow-wrap: anywhere;
}
.dead-agent {
  filter: grayscale(1);
  opacity: 0.55;
}

/* Versioned primitive terrain; legacy scenes retain their existing appearance. */
.cell.terrain-river {
  background: #306776;
}
.cell.terrain-shallow {
  background: repeating-linear-gradient(135deg, #8eb6ad 0 5px, #b7cbb3 5px 7px);
}
.environment-token {
  position: absolute;
  inset: 8%;
  display: grid;
  place-items: center;
}
.environment-token svg {
  width: 100%;
  height: 100%;
}
.toxic-resource {
  filter: hue-rotate(55deg);
}
.capability-panel {
  padding: 24px;
}
.capability-panel .panel-heading {
  padding: 0 0 18px;
}
.learning-progress {
  padding: 12px;
  border-left: 2px solid #b89358;
  background: #f0f2e7;
}
.learned-skill {
  margin: 12px 0;
  overflow-wrap: anywhere;
}
.learned-skill summary {
  cursor: pointer;
  color: #365d48;
  font-weight: 600;
}
.learned-skill p,
.resource-detail {
  font-size: 12px;
  line-height: 1.6;
  overflow-wrap: anywhere;
}
.resource-detail {
  border-bottom: 1px solid #e8ecdf;
  padding-bottom: 8px;
}
.toxic-detail {
  color: #92583c;
}

/* Version 5 ecology uses authored symbols and observable appearances only. */
.map-scale-control {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  padding: 10px 16px;
  font-size: 12px;
}
.map-scale-control span {
  flex-basis: 100%;
  color: var(--muted);
}
.map-scale-control[hidden] {
  display: none;
}
.evolution-map {
  overflow: auto;
  max-width: 100%;
}
.evolution-map .map-row,
.evolution-map .x-axis {
  min-width: var(--map-width, 0px);
}
.cell.biome-forest {
  background: #28513d;
}
.cell.biome-grassland {
  background: #49623c;
}
.cell.biome-rocky {
  background: #515a56;
}
.cell.biome-damp {
  background: #4c455c;
}
.cell.biome-bank {
  background: #7a7350;
}
.cell.biome-river {
  background: #2d5d76;
}
.cell.biome-shallow {
  background: #5f9fa2;
}
.evolution-map .cell.visible {
  box-shadow: inset 0 0 0 1px #d4d29244;
}
.evolution-map .agent-token {
  min-width: 12px;
  min-height: 12px;
  z-index: 3;
