  actionEffort,
} from '../src/index.js';
import type {
  CoevolutionAction,
  CoevolutionProposal,
  ObjectBlueprint,
  WorldState,
} from '../src/index.js';
const empty = EMPTY_COEVOLUTION_PROPOSAL;
const object: ObjectBlueprint = {
  id: 'woven-support',
