      proposal: CoevolutionProposal = {
        ...base,
        mechanics: base.mechanics.map((m) => ({
          ...m,
          code: JSON.stringify([
            operation('place', null, blueprint.id, 1, [
              { resource: 'branch', quantity: 1 },
              { resource: 'food', quantity: 1 },
            ]),
          ]),
        })),
