    expect(interrupted.actors[0]?.vitals.energy).toBe(39);
    expect(interrupted.actors[0]?.extensionState).toEqual({});
    expect(step(interrupted, observe).outcomes.a?.complete).toBe(false);
    const missing = v7Clone(first);
