import { v7Clone, v7Install, v7Step } from '@self-evolving-world/world-core';
import type { V7World } from '@self-evolving-world/world-core';
import {
  fireFixture,
  fireRegistry,
  fireWait,
  fireOperation,
} from './local-fire.js';
export function willowFixture() {
  let w = fireFixture();
  w.tick = 100;
  w.time = 100;
  w.actors.forEach((a) => {
    a.vitals.temperature = 20;
  });
  w.objects.push({
    id: 'isolated-willow',
    kind: 'tree',
    name: 'Observed willow',
    spatial: {
      x: 11,
      y: 10,
      angle: 0,
      shape: { kind: 'circle', radius: 0.5 },
      solid: true,
      interaction: 0.65,
      entrances: [],
    },
    visual: {
      component: 'tree',
      color: '#61865a',
      accent: '#9d8c66',
      label: 'Willow',
      state: 'standing',
    },
    data: {
      resource: 'willow',
      stock: 3,
      capacity: 3,
      interval: 0,
      growth: 0,
      produced: 0,
    },
    createdBy: null,
    createdAt: 0,
    revision: 'foundation-forest@1',
  });
