  );
  expect(w.objects.filter((o) => o.kind === 'canopy-post')).toHaveLength(4);
  expect(mass(w)).toBeCloseTo(total);
  expect(canopyCover(w, { x: 10, y: 8.5 }, 0.24)).toBeUndefined();
