  expect(actor(w).vitals.energy).toBeCloseTo(actor(before).vitals.energy - 2.6);
  expect(v7Load(w, actor(w))).toBeCloseTo(v7Load(before, actor(before)), 7);
  expect(j.stage).toBe(6);
