  expect(result.absoluteBounds).toBeNull();
  expect(result.absoluteCertificateValid).toBe(false);
  expect(
    (frames[5]?.state['contact:project:lin:contact-study'] as V7Data).status,
  ).toBe('awaiting-assessment');
  expect(
