  v7Step,
} from '@self-evolving-world/world-core';
const root = process.cwd(),
  capture = process.env.WORLD_EXPERIMENT_CAPTURE;
async function screenshot(
  page: Page,
  info: TestInfo,
  name: string,
): Promise<string> {
  expect(
    await page.evaluate(
      () => document.documentElement.scrollWidth <= innerWidth + 1,
