    w = v7Clone(r.world);
  };
  for (let i = 0; i < 4; i++)
    execute(
      i
        ? wait
        : { interface: 'learn', args: { ability: 'portable-insulation' } },
    );
  execute({ interface: 'portable-insulation', args: { mode: 'craft' } });
  const frames = [v7Clone(w)];
  for (let i = 1; i < 5; i++)
    execute({ interface: 'portable-insulation', args: { mode: 'craft' } });
