export function measureContinuous(
  state: V7Execution,
  frames: V7World[],
  records: V7ReplaySegment['rounds'],
) {
  const events = records.flatMap((r) => r.events),
    final = state.world;
  const historicalObjects = new Map(
    frames.flatMap((frame) =>
      frame.objects.map((object) => [object.id, object] as const),
    ),
  );
  const totalActions = records.reduce(
    (n, r) => n + Object.keys(r.actions).length,
    0,
  );
  const actions: Record<
    string,
    { attempted: number; successful: number; failed: number }
  > = {};
  for (const round of records)
    for (const [actor, action] of Object.entries(round.actions)) {
      const value = (actions[action.interface] ??= {
        attempted: 0,
        successful: 0,
        failed: 0,
      });
      value.attempted++;
      if (round.events.some((e) => e.actor === actor && e.type === 'failed'))
        value.failed++;
      else value.successful++;
    }
  const roles = (['ordinary', 'world'] as const).map((role) => {
    const attempts = state.attempts.filter((a) => a.role === role);
    return {
      role,
      attempts: attempts.length,
      accepted: attempts.filter((a) => a.status === 'accepted').length,
      failedOrRejected: attempts.filter((a) =>
        ['failed', 'rejected'].includes(a.status),
      ).length,
      inputTokens: attempts.reduce(
        (n, a) => n + (a.usage?.inputTokens ?? 0),
        0,
      ),
      outputTokens: attempts.reduce(
        (n, a) => n + (a.usage?.outputTokens ?? 0),
        0,
      ),
      unknownUsageAttempts: attempts.filter((a) => !a.usage).length,
      elapsedMs: attempts.reduce((n, a) => n + (a.elapsedMs ?? 0), 0),
    };
  });
  return {
    ...(final.config.development
      ? { openDevelopment: measureOpen(state, frames, records) }
      : {}),
    version: 7,
    observedRounds: final.tick,
    targetWindow: state.windowTarget,
    phase: state.phase,
    reason: state.reason,
    totalActions,
    framesChecked: frames.length,
    invariantFailures: 0,
    ...(final.config.forest
      ? {
          forest: {
            model: state.model,
            seed: final.config.seed,
            deaths: events.filter((e) => e.type === 'died'),
            respawns: events.filter((e) => e.type === 'respawned'),
            seasons: [...new Set(frames.map((f) => f.state.season))],
            lives: final.actors.map((a) => ({ id: a.id, life: a.life })),
            zeroRecoveryRest: events.filter(
              (e) => e.type === 'rested' && e.data.recovered === 0,
            ).length,
            monetaryCost: null,
            monetaryCostNote:
              'Plan-funded transport; per-call monetary charges and internal development usage are not metered.',
          },
        }
      : {}),
    ...(final.config.experience
      ? {
          experience: {
            counting:
              'Action counts measure executed rounds, including progress rounds. Initial non-authored interfaces may be learned but are not newly developed. Completed operation events and measured physical effects are separate evidence. Pre-action reference invalidations can trigger a decision without a failed execution event.',
            referenceDecisionInvalidations: state.attempts
              .filter(
                (a) =>
                  a.role === 'ordinary' &&
                  /Reference (?:unavailable|ambiguous|insufficient|wrong-kind|reserved|invalid)/.test(
                    a.reason,
                  ),
              )
              .map((a) => ({
                call: a.id,
                tick: a.tick,
                actor: a.actor,
                reason: a.reason,
                status: a.status,
              })),
            learnedBaselineInterfaces: final.actors.map((a) => ({
              actor: a.id,
              abilities: a.mastered.filter((id) =>
                frames[0]?.abilities.some(
                  (old) => old.id === id && !old.authored,
                ),
              ),
            })),
            developedInterfaceExecution: final.abilities
              .filter(
                (a) => !frames[0]?.abilities.some((old) => old.id === a.id),
              )
              .map((a) => ({
                id: a.id,
                personallyMasteredBy: final.actors
                  .filter((actor) => actor.mastered.includes(a.id))
                  .map((actor) => actor.id),
                executionRounds: records.flatMap((r) =>
                  Object.entries(r.actions)
                    .filter(([, action]) => action.interface === a.id)
                    .map(([actor]) => ({
                      tick: r.tick,
                      actor,
                      failed: r.events.some(
                        (e) => e.actor === actor && e.type === 'failed',
                      ),
                    })),
                ),
                completedOperations: events.filter(
                  (e) =>
                    e.interface === a.id &&
                    e.actor !== null &&
                    e.success &&
                    (e.type.endsWith('-completed') ||
                      [
                        'insulation-equipped',
                        'insulation-unequipped',
                        'fire-fed',
                        'fire-extinguished',
                      ].includes(e.type)),
                ),
              })),
            referenceFailures: events.filter(
              (e) =>
                e.type === 'failed' &&
                typeof e.data.reasonCode === 'string' &&
                e.data.reasonCode.startsWith('reference-'),
            ),
            completedOperationEvents: events.filter((e) =>
              e.type.endsWith('-completed'),
            ),
            messageDecisionReasons: state.attempts
              .filter((a) => a.role === 'ordinary' && /message/.test(a.reason))
              .map((a) => ({
                id: a.id,
                actor: a.actor,
                tick: a.tick,
                reason: a.reason,
              })),
            decisionRate:
              state.attempts.filter((a) => a.role === 'ordinary').length /
              Math.max(1, final.tick * final.actors.length),
            meals: events.filter((e) => e.type === 'meal-experience'),
            recovery: events
              .filter((e) => e.type === 'rested')
              .map((e) => ({ tick: e.tick, actor: e.actor, ...e.data })),
            trajectories: frames
              .filter((f) => f.tick % 20 === 0 || f.tick === final.tick)
              .map((f) => ({
                tick: f.tick,
                actors: f.actors.map((a) => ({
                  id: a.id,
                  vitals: a.vitals,
                  mental: a.experience?.mental,
                  pleasure: a.experience?.pleasure,
                  monotony: a.experience?.monotony,
                })),
              })),
            baselineInterfaces: frames[0]?.abilities.map((a) => a.id) ?? [],
            newlyImplemented: final.abilities
              .filter(
                (a) => !frames[0]?.abilities.some((old) => old.id === a.id),
              )
              .map((a) => ({ id: a.id, equivalence: a.equivalence })),
            failedActions: events.filter((e) => e.type === 'failed'),
            benefits: events.filter((e) =>
              /benefit|qualified|exposure|relief/.test(e.type),
            ),
          },
        }
      : {}),
    actors: final.actors.map((actor) => {
      const history = frames.flatMap((f) =>
          f.actors.filter((a) => a.id === actor.id),
        ),
        happiness = history.map((a) => a.wellbeing.total),
        named = events.filter((e) => e.actor === actor.id);
      return {
        id: actor.id,
        alive: actor.vitals.health > 0,
        finalVitals: actor.vitals,
        minimumHealth: Math.min(...history.map((a) => a.vitals.health)),
        minimumSatiety: Math.min(...history.map((a) => a.vitals.satiety)),
        finalWellbeing: actor.wellbeing,
        meanWellbeing:
          happiness.reduce((a, b) => a + b, 0) / Math.max(1, happiness.length),
        peakWellbeing: Math.max(...happiness),
        roundsAtLeast50: happiness.filter((v) => v >= 50).length,
        requests: named.filter((e) => e.type === 'requested').length,
        studyRounds: named.filter((e) =>
          ['learning', 'mastered'].includes(e.type),
        ).length,
        newlyMastered: actor.mastered.filter(
          (key) => !final.abilities.find((a) => a.id === key)?.authored,
        ),
        successfulNewAbilityUses: records.filter((round) => {
          const action = round.actions[actor.id];
          return (
            action &&
            final.abilities.some(
              (ability) => ability.id === action.interface && !ability.authored,
            ) &&
            !round.events.some(
              (event) => event.actor === actor.id && event.type === 'failed',
            )
          );
        }).length,
        successfulNewAbilityEvents: named.filter(
          (e) =>
            e.success &&
            e.interface &&
            !final.abilities.find((a) => a.id === e.interface)?.authored &&
            !['mastered', 'learning', 'satisfaction'].includes(e.type),
        ).length,
        movementDistance: named
          .filter((e) => ['moved', 'arrived'].includes(e.type))
          .reduce((n, e) => n + Number(e.data.distance ?? 0), 0),
        finalNotes: actor.memory.notes,
        finalPreferences: actor.memory.preferences,
      };
    }),
    calls: roles,
    development: {
      handoffs: state.developments.length,
      accepted: state.developments.filter((d) => d.status === 'accepted')
        .length,
      failed: state.developments.filter((d) => d.status === 'failed').length,
      internalModelCalls: null,
      inputTokens: null,
      outputTokens: null,
      limitation:
        'Current-conversation development handoffs are counted before work. Internal coding/reasoning calls, tokens and preparation/review costs are not directly metered; these unknown costs are not zero.',
    },
    actions,
    implementedAbilities: final.abilities
      .filter((a) => !a.authored)
      .map((a) => ({
        id: a.id,
        name: a.name,
        revision: a.revision,
        learning: a.learning,
        masteredBy: final.actors
          .filter((p) => p.mastered.includes(a.id))
          .map((p) => p.id),
        successfulEvents: events.filter(
          (e) => e.success && e.interface === a.id,
        ).length,
      })),
    requests: state.attempts
      .filter((a) => a.role === 'world')
      .map((a) => ({ call: a.id, tick: a.tick, status: a.status })),
    persistentObjects: final.objects.filter((o) => o.createdBy),
    sources: final.satisfaction,
    processes: final.processes,
    revisions: final.revisions,
    objectLifecycle: {
      created: [...historicalObjects.values()].filter(
        (o) => o.createdBy !== null,
      ).length,
      removed: [...historicalObjects.values()].filter(
        (o) => !final.objects.some((current) => current.id === o.id),
      ).length,
    },
    crossActorObjectEvents: events
      .filter(
        (e) =>
          e.success &&
          e.actor !== null &&
          e.target &&
          [...historicalObjects.values()].some(
            (o) => o.id === e.target && o.createdBy && o.createdBy !== e.actor,
          ),
      )
      .map((e) => ({
        tick: e.tick,
        actor: e.actor,
        type: e.type,
        interface: e.interface,
        target: e.target,
        data: e.data,
      })),
    socialEvents: events.filter((e) =>
      ['message', 'given', 'consented', 'born'].includes(e.type),
    ),
    satisfactionEvents: events
      .filter((e) => e.type === 'satisfaction')
      .map((e) => ({ tick: e.tick, actor: e.actor, data: e.data })),
    stages: state.stages,
  };
}
export function continuousChart(state: V7Execution, frames: V7World[]): string {
  const width = 1120,
    height = 620,
    x = (tick: number) => 70 + (tick / Math.max(1, state.world.tick)) * 980,
    y = (value: number) => 470 - value * 3.5;
  const colors = ['#bb8a4c', '#557e5c', '#568d9e'];
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${String(width)}" height="${String(height)}" viewBox="0 0 ${String(width)} ${String(height)}" role="img" aria-label="Measured wellbeing over recorded rounds"><rect width="1120" height="620" fill="#f4f5ec"/><text x="64" y="55" font-family="Georgia,serif" font-size="30" fill="#214838">Life in a continuous world</text><text x="64" y="85" font-family="sans-serif" font-size="13" fill="#687a64">${String(state.world.tick)} observed rounds · ${state.phase} · wellbeing 0–100 · individual mechanisms are not causal treatments</text>${[0, 25, 50, 75, 100].map((v) => `<path d="M70 ${String(y(v))}H1050" stroke="#d7dece"/><text x="38" y="${String(y(v) + 4)}" font-family="sans-serif" font-size="12" fill="#7b8a73">${String(v)}</text>`).join('')}${state.world.actors
    .map(
      (a, i) =>
        `<polyline points="${frames
          .flatMap((f) => {
            const p = f.actors.find((p) => p.id === a.id);
            return p
              ? [`${x(f.tick).toFixed(2)},${y(p.wellbeing.total).toFixed(2)}`]
              : [];
          })
          .join(
            ' ',
          )}" fill="none" stroke="${String(colors[i % colors.length])}" stroke-width="2.4"/><circle cx="${String(80 + i * 230)}" cy="540" r="5" fill="${String(colors[i % colors.length])}"/><text x="${String(94 + i * 230)}" y="545" font-family="sans-serif" font-size="14" fill="#31513e">${a.id} · final ${a.wellbeing.total.toFixed(1)}</text>`,
    )
    .join(
      '',
    )}<text x="70" y="495" font-family="sans-serif" font-size="12" fill="#71816b">0</text><text x="1010" y="495" font-family="sans-serif" font-size="12" fill="#71816b">${String(state.world.tick)}</text><text x="70" y="585" font-family="sans-serif" font-size="12" fill="#71816b">Physical comfort contributes at most 10. Other sources require implemented, successful world events.</text></svg>`;
}
export function continuousReport(
  id: string,
  state: V7Execution,
  results: ReturnType<typeof measureContinuous>,
): string {
  const forestSummary = state.world.config.forest
    ? `## Forest lifecycle and environment\n\nModel: ${state.model}. Seed: ${String(state.world.config.seed)}. Observed seasons: ${results.forest?.seasons.map((s) => (typeof s === 'string' ? s : 'unknown')).join(', ') ?? 'unknown'}. Deaths and respawns are retained with exact evidence and prior plans in results.json. Full-state replay remains independent of rendering. Monetary cost and internal developer usage are unknown; recorded role-specific tokens below are measured. These formal events are distinct from isolated forest-lab fixtures.\n\n${state.world.actors.map((a) => `${a.name}: ${String(a.life?.deaths ?? 0)} deaths, ${String((a.life?.total ?? 0) - (a.life?.deaths ?? 0))} remaining lives.`).join('\n\n')}\n\n`
    : '';
  return `# ${id}: Continuous World and Persistent Wellbeing\n\n## Scope and observation window\n\n${state.world.config.development ? OPEN_OBJECTIVE : state.world.config.experience ? EXPERIENCE_OBJECTIVE : CONTINUOUS_OBJECTIVE}\n\nObserved ${String(state.world.tick)} of ${String(state.windowTarget)} target rounds. State: ${state.phase}. ${state.reason ?? ''} This is one exploratory combined experiment; no individual mechanism has a causal estimate. No model-weight training occurred.\n\n## Measured outcome\n\n| Actor | Alive | Health | Satiety | Mean happiness | Final happiness | Newly mastered | ${state.world.config.experience ? 'Learned-interface successful rounds' : 'New-ability successful rounds'} |\n| --- | --- | --- | --- | --- | --- | --- | --- |\n${results.actors.map((a) => `| ${a.id} | ${String(a.alive)} | ${String(a.finalVitals.health)} | ${String(a.finalVitals.satiety)} | ${a.meanWellbeing.toFixed(2)} | ${a.finalWellbeing.total.toFixed(2)} | ${String(a.newlyMastered.length)} | ${String(a.successfulNewAbilityUses)} |`).join('\n')}\n\nRequests, reviews, implementation, individual study, successful execution and lasting satisfaction are separate records in calls, source-history, replay events and results.json. Event counts are not unique skills or demonstrated lasting benefits.${state.world.config.development ? ' This fresh policy inherits no generated interfaces. The explicit authored allowlist, current-run package provenance, personal projects, verified knowledge, trials and persistent processes are retained separately in results.openDevelopment. Actor-written progress is a claim, not a physical outcome.' : state.world.config.experience ? ' In this policy the table includes personally learned baseline interfaces; results.experience separately lists newly developed interfaces, personal mastery, completed operations and pre-action reference invalidations. The initial ex8 catalogue is not new ex9 discovery.' : ''} Initial survival interfaces and established perennial food are authored baseline, not autonomous discoveries.\n\n## Action distribution\n\n| Interface | Attempted | Successful rounds | Failed rounds |\n| --- | --- | --- | --- |\n${Object.entries(
    results.actions,
  )
    .map(
      ([key, a]) =>
        `| ${key} | ${String(a.attempted)} | ${String(a.successful)} | ${String(a.failed)} |`,
    )
    .join(
      '\n',
    )}\n\n## Cost and limitations\n\n${results.calls.map((c) => `${c.role}: ${String(c.attempts)} attempted calls, ${String(c.failedOrRejected)} failed/rejected; ${String(c.inputTokens)} recorded input tokens and ${String(c.outputTokens)} recorded output tokens; ${String(c.unknownUsageAttempts)} attempts with unknown token usage; ${(c.elapsedMs / 1000).toFixed(1)} elapsed seconds.`).join('\n\n')}\n\n${String(results.development.handoffs)} pre-counted conversation development handoffs, ${String(results.development.failed)} failed validation attempts. ${results.development.limitation}\n\n## Evidence and reproduction\n\nConfiguration and isolated survival feasibility are in configuration.json and preflight.json. The feasibility oracle and isolated extension fixtures never enter ordinary decision context. Every actual inference has an immutable calls/ record, including transport failures. replay.json indexes checksummed segments; source-history.json binds retained source, packages, tests and activation boundaries. The observatory reconstructs saved rounds; playback cannot advance the world.\n\nRun \`pnpm experiment:check\` and \`pnpm test\` to validate saved evidence. Open \`/observatory.html?experiment=${id}\` for the game view. Use the current task's development handoff to continue a pending barrier; do not allocate a replacement run or repeat an uncertain call.\n\n${forestSummary}## Interpretation\n\nThe current-conversation behavioral analysis accompanies this archive and traces actual problems, proposed functions, review, implementation, use and consequences. Shared object use is distinguished from explicit communication or consent. Novel names, proposals, installations and offspring counts are not happiness rewards. The observation window is resumable; completed capture is not world termination.\n`;
}
export function continuousArtifactFiles(
  manifest: Record<string, unknown>,
): string[] {
  const list = manifest.files;
  if (
    !Array.isArray(list) ||
    list.some(
      (p) =>
        typeof p !== 'string' ||
        p.startsWith('/') ||
        p.includes('..') ||
        p.includes('\\'),
    ) ||
    new Set(list).size !== list.length
  )
    throw new Error('Invalid continuous artifact index.');
  return list as string[];
}
export function readContinuousExperiment(
  root: string,
  id: string,
  manifest: Record<string, unknown>,
  pending: boolean,
) {
  const directory = resolve(root, 'experiment', id),
    state = readContinuousExecution(root, id),
    index = continuousRead<V7ReplayIndex>(resolve(directory, 'replay.json'));
  if (
    manifest.version !== 7 ||
    manifest.controller !== 'chatgpt-plan' ||
    manifest.id !== id ||
    index.observed !== state.world.tick ||
    (index as { version: unknown }).version !== 7 ||
    state.controller !== 'chatgpt-plan' ||
    !['paused', 'window-complete'].includes(state.phase) ||
    (!pending && manifest.status !== 'completed')
  )
    throw new Error('Invalid or unfinished continuous archive.');
  const frames: V7World[] = [],
    rounds: V7ReplaySegment['rounds'] = [];
  for (const part of index.segments) {
    const path = resolve(directory, part.path);
    if (
      !/^replay\/(?:part|execution)-\d+(?:-\d+)?\.json$/.test(part.path) ||
      continuousHash(readFileSync(path, 'utf8')) !== part.sha256
    )
      throw new Error('Invalid continuous replay segment.');
    const segment = continuousRead<V7ReplaySegment>(path),
      values = reconstructContinuousSegment(segment);
    if (frames.length && v7Signature(frames.at(-1)) !== v7Signature(values[0]))
      throw new Error('Segment boundaries do not join exactly.');
    frames.push(...(frames.length ? values.slice(1) : values));
    rounds.push(...segment.rounds);
  }
  if (
    continuousHash(frames.at(-1)) !== continuousHash(state.world) ||
    frames.length !== state.world.tick + 1
  )
    throw new Error(
      'Reconstructed final state differs from the durable checkpoint.',
    );
  for (const attempt of state.attempts) {
    if (
      !existsSync(resolve(directory, 'calls', `${attempt.id}.json`)) &&
      attempt.status === 'started' &&
      state.pendingCall?.id === attempt.id &&
      state.phase === 'paused'
    )
      continue;
    const call = continuousRead<V7CallRecord>(
      resolve(directory, 'calls', `${attempt.id}.json`),
    );
    if (continuousHash(call.attempt) !== continuousHash(attempt))
      throw new Error('Call ledger disagrees with durable raw record.');
  }
  for (const revision of continuousHistory(root, id)) {
    const files = continuousRead<Record<string, string>>(
      resolve(directory, 'sources', `revision-${String(revision.id)}.json`),
    );
    if (
      continuousHash(files) !== revision.sourceHash ||
      Object.entries(files).some(
        ([p, s]) => continuousHash(s) !== revision.files[p],
      )
    )
      throw new Error('Retained source revision failed integrity validation.');
  }
  const results = measureContinuous(state, frames, rounds);
  if (
    continuousHash(continuousRead(resolve(directory, 'results.json'))) !==
    continuousHash(results)
  )
    throw new Error('Continuous measurements disagree with saved events.');
  if (!pending) {
    const artifacts = manifest.artifacts as Record<string, unknown> | undefined;
    if (!artifacts) throw new Error('Missing continuous artifact hashes.');
    for (const file of continuousArtifactFiles(manifest)) {
      const path = resolve(directory, file);
      if (
        !lstatSync(path).isFile() ||
        artifacts[file] !== continuousHash(readFileSync(path))
      )
        throw new Error(`Continuous artifact hash mismatch: ${file}`);
    }
    const browser = continuousRead<{
      status: string;
      replayHash: string;
      assertions: string[];
      frameTicks: number[];
      errors: unknown[];
    }>(resolve(directory, 'browser.json'));
    if (
      browser.status !== 'passed' ||
      browser.replayHash !==
        continuousHash(readFileSync(resolve(directory, 'replay.json'))) ||
      v7Signature(browser.assertions) !== v7Signature(CONTINUOUS_ASSERTIONS) ||
      v7Signature(browser.frameTicks) !==
        v7Signature([0, Math.floor(state.world.tick / 2), state.world.tick]) ||
      browser.errors.length
    )
      throw new Error('Missing current continuous browser evidence.');
  }
  return {
    directory,
    manifest,
    config: {
      id,
      objective: CONTINUOUS_OBJECTIVE,
      steps: state.world.tick,
      schedule: 'continuous-v1' as const,
      totalActions: results.totalActions,
    },
    run: { frames: [] as WorldState[] },
    continuous: {
      initial: frames[0],
      final: state.world,
      frames: Object.fromEntries(
        [0, Math.floor(state.world.tick / 2), state.world.tick].map((tick) => [
          tick,
          frames[tick],
        ]),
      ),
    },
    results,
  };
}

scripts/continuous-cli.ts:
import { OPEN_OBJECTIVE } from './open-analysis.js';
import { renewableAccessToken } from '../apps/simulator/src/chatgpt-renewal.js';
import { prepareContinuousWindow } from './continuous-window.js';
import { resolve } from 'node:path';
import { writeFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { initialOpenWorld } from '../apps/simulator/src/open-scenario.js';
import { openPreflight } from './open-preflight.js';
import type { V7World } from '@self-evolving-world/world-core';
import { selectModel } from '../apps/simulator/src/responses.js';
import { continuousProvider } from '../apps/simulator/src/continuous-provider.js';
import {
  continueContinuousExecution,
  newContinuousExecution,
  issueContinuousDevelopment,
} from '../apps/simulator/src/continuous-run.js';
import type { V7Execution } from '../apps/simulator/src/continuous-run.js';
import { requireTaskWorker } from './task-worker.js';
import { allocateExperiment, checkExperiments } from './experiments.js';
import {
  continuousAtomic,
  continuousRead,
  continuousSink,
  buildContinuousReplay,
  reconstructContinuousSegment,
  continuousArchivePaths,
} from './continuous-store.js';
import type { V7ReplaySegment } from './continuous-store.js';
import { continuousCheckpoint } from './continuous-files.js';
import {
  saveContinuousSource,
  captureContinuousBaseline,
} from './continuous-source.js';
import {
  measureContinuous,
  continuousChart,
  continuousReport,
} from './continuous-analysis.js';

const root = process.cwd();
try {
  const context = requireTaskWorker(
    root,
    'continuous',
    process.argv.slice(2).filter((a) => a !== '--'),
  );
  if (!context.experiment)
    throw new Error('Missing experiment allocation journal.');
  let id = context.experiment.id,
    state: V7Execution,
    token: string | undefined;
  if (!id) {
    checkExperiments(root);
    const preflight = {
      baseline: openPreflight(),
    };
    token = await renewableAccessToken();
    const model = await selectModel(token, 'gpt-6.1-sol');
    id = allocateExperiment(root);
    context.experiment.id = id;
    continuousAtomic(
      resolve(root, 'validation-results/tasks', `${context.intent.id}.json`),
      context,
    );
    const directory = resolve(root, 'experiment', id),
      git = (...args: string[]) =>
        execFileSync('git', args, { cwd: root, encoding: 'utf8' }).trim();
    state = newContinuousExecution(
      model,
      'chatgpt-plan',
      initialOpenWorld(`open-${id}`),
    );
    continuousAtomic(resolve(directory, 'manifest.json'), {
      format: 'self-evolving-world/experiment',
      version: 7,
      id,
      objective: OPEN_OBJECTIVE,
      schedule: 'continuous-v1',
      controller: 'chatgpt-plan',
      steps: 0,
      targetWindow: state.windowTarget,
      status: 'running',
      externalModelCalls: 0,
      createdAt: new Date().toISOString(),
      provenance: {
        revision: git('rev-parse', 'HEAD'),
        dirty: git('status', '--porcelain') !== '',
        node: process.version,
        platform: process.platform,
      },
      files: [],
    });
    continuousAtomic(
      resolve(directory, 'configuration.json'),
      state.world.config,
    );
    continuousAtomic(resolve(directory, 'preflight.json'), preflight);
    continuousAtomic(resolve(directory, 'initial.json'), state.world);
    continuousAtomic(resolve(directory, 'execution.json'), state);
    saveContinuousSource(
      root,
      id,
      state,
      'Initial open-development-v1 fresh policy, inheritSkills=false, with only the explicit authored baseline. No historical generated skills, objects, rewards or mastery. Offline policies and composition fixtures are excluded from ordinary inputs.',
    );
  } else {
    const previous = continuousRead<Record<string, unknown>>(
      resolve(root, 'experiment', id, 'manifest.json'),
    );
    if (
      previous.status === 'completed' &&
      context.intent.experiment.mode === 'continuous' &&
      context.intent.experiment.allocation === 'reuse' &&
      context.intent.experiment.rounds !== undefined
    )
      prepareContinuousWindow(root, id, context.intent.experiment.rounds);
    state = continuousCheckpoint(root, id);
  }
  const directory = resolve(root, 'experiment', id),
    sink = continuousSink(root, id),
    manifestPath = resolve(directory, 'manifest.json');
  const manifest = continuousRead<Record<string, unknown>>(manifestPath);
  if (manifest.status === 'completed')
    throw new Error(
      'A captured observation window cannot be overwritten; continuation requires an explicitly preserved new window.',
    );
  if (
    state.phase === 'development' &&
    state.developments.find((a) => a.id === state.barrier?.developmentAttempt)
      ?.status === 'failed'
  ) {
    await issueContinuousDevelopment(state, sink);
  }
  if (state.phase === 'running' || state.pendingCall) {
    token ??= await renewableAccessToken();
    state = await continueContinuousExecution(
      state,
      continuousProvider(renewableAccessToken, state.model),
      sink,
    );
  }
  await sink.save(state);
  continuousAtomic(manifestPath, {
    ...manifest,
    steps: state.world.tick,
    externalModelCalls: state.attempts.length,
    windowPhase: state.phase,
  });
  if (state.phase === 'development') {
    captureContinuousBaseline(root, id, state);
    console.log(
      JSON.stringify({
        status: 'needs_development',
        experiment: id,
        barrier: state.barrier,
        budget: state.world.config.budgets,
        attempts: state.developments,
        declaration: {
          packages: ['package-id@version'],
          paths: ['Every changed source or visual path'],
          assignments: { requester: 'implemented-interface' },
          review:
            'Concrete implementation, geometry, costs, duration, happiness, dependencies, migration and visual review.',
        },
      }),
    );
  }
  if (['paused', 'window-complete'].includes(state.phase)) {
    const initial = continuousRead<V7World>(resolve(directory, 'initial.json')),
      index = buildContinuousReplay(root, id, initial, state),
      frames: V7World[] = [],
      rounds: V7ReplaySegment['rounds'] = [];
    for (const part of index.segments) {
      const segment = continuousRead<V7ReplaySegment>(
          resolve(directory, part.path),
        ),
        values = reconstructContinuousSegment(segment);
      frames.push(...(frames.length ? values.slice(1) : values));
      rounds.push(...segment.rounds);
    }
    const results = measureContinuous(state, frames, rounds);
    continuousAtomic(resolve(directory, 'results.json'), results);
    writeFileSync(
      resolve(directory, 'report.md'),
      continuousReport(id, state, results),
    );
    writeFileSync(
      resolve(directory, 'overview.svg'),
      continuousChart(state, frames),
    );
    continuousAtomic(manifestPath, {
      ...manifest,
      steps: state.world.tick,
      externalModelCalls: state.attempts.length,
      windowPhase: state.phase,
      files: [
        ...new Set([
          ...continuousArchivePaths(directory),
          'browser.json',
          'initial.png',
          'midpoint.png',
          'final.png',
          'overview.png',
        ]),
      ].sort(),
    });
    console.log(
      `${id}: ${state.phase} at round ${String(state.world.tick)}; raw evidence retained. The existing coordinator will capture and review the observation.`,
    );
  }
} catch (error) {
  console.error(
    error instanceof Error ? error.message : 'Continuous experiment failed.',
  );
  process.exitCode = 1;
}

scripts/continuous-files.ts:
import { v7Clone } from '@self-evolving-world/world-core';
import { resolveContinuousDevelopment } from '../apps/simulator/src/continuous-run.js';
import { resolve } from 'node:path';
import {
  continuousAtomic,
  readContinuousExecution,
} from './continuous-store.js';
import {
  currentContinuousRuntimeMatches,
  captureContinuousBaseline,
  validateContinuousDevelopment,
  saveContinuousSource,
} from './continuous-source.js';

export function continuousCheckpoint(root: string, id: string) {
  const state = readContinuousExecution(root, id);
  if (
    !currentContinuousRuntimeMatches(root, id) &&
    state.phase !== 'development'
  )
    throw new Error(
      'Continuous run source changed outside a versioned development handoff.',
    );
  captureContinuousBaseline(root, id, state);
  return state;
}
export function submitContinuousDevelopment(
  root: string,
  id: string,
  input: unknown,
): void {
  const state = continuousCheckpoint(root, id),
    attempt = state.developments.find(
      (a) => a.id === state.barrier?.developmentAttempt,
    );
  if (!state.barrier || !attempt || attempt.status !== 'started')
    throw new Error('No current, pre-counted development attempt.');
  const path = resolve(root, 'experiment', id, 'execution.json');
  try {
    const accepted = validateContinuousDevelopment(root, id, state, input);
    const reviewed = v7Clone(state);
    if (!reviewed.barrier) throw new Error('Missing validated review barrier.');
    reviewed.barrier.reviews = accepted.reviews;
    const resolved = resolveContinuousDevelopment(
      reviewed,
      accepted.packages,
      accepted.assignments,
      accepted.review,
    );
    saveContinuousSource(
      root,
      id,
      resolved,
      accepted.review,
      accepted.validation,
    );
    continuousAtomic(
      resolve(
        root,
        'experiment',
        id,
        'development',
        `${attempt.id}-declaration.json`,
      ),
      input,
    );
    continuousAtomic(path, resolved);
  } catch (error) {
    attempt.status = 'failed';
    attempt.finishedAt = new Date().toISOString();
    attempt.reason =
      error instanceof Error ? error.message : 'Development validation failed.';
    state.phase = 'development';
    state.reason = attempt.reason;
    continuousAtomic(path, state);
    throw error;
  }
}

scripts/continuous-preflight.ts:
import {
  continuousRegistry,
  v7Step,
  v7Reach,
  v7Distance,
  v7Observe,
} from '@self-evolving-world/world-core';
import type { V7Action } from '@self-evolving-world/world-core';
import { initialContinuousWorld } from '../apps/simulator/src/continuous-scenario.js';

/** An explicitly simulated feasibility oracle. This policy is never imported by model input or execution. */
export function continuousPreflight(rounds = 1000) {
  let world = initialContinuousWorld();
  const initial = world,
    calls = 0,
    actions: Record<string, number> = {},
    firstMeals: Record<string, number> = {},
    distance: Record<string, number> = {},
    minimumSatiety: Record<string, number> = {},
    minimumHealth: Record<string, number> = {};
  for (let tick = 0; tick < rounds; tick++) {
    const intents: Record<string, V7Action> = {};
    for (const actor of world.actors) {
      const owned = world.stacks.find(
        (s) =>
          s.owner === actor.id &&
          world.resources.some((r) => r.id === s.resource && r.nutrition > 0),
      );
      if (actor.vitals.energy < 4)
        intents[actor.id] = { interface: 'rest', args: {} };
      else if (actor.vitals.satiety < 78 && owned)
        intents[actor.id] = {
          interface: 'eat',
          args: { target: owned.id, quantity: 1 },
        };
      else if (actor.vitals.satiety < 78) {
        const source = v7Observe(world, actor.id)
          .objects.filter(
            (o) =>
              Number(o.data.stock) > 0 &&
              world.resources.some(
                (r) => r.id === o.data.resource && r.nutrition > 0,
              ),
          )
          .sort(
            (a, b) =>
              v7Distance(actor.position, a.spatial) -
              v7Distance(actor.position, b.spatial),
          )[0];
        if (!source)
          throw new Error(
            'Offline survival feasibility has no observed food source.',
          );
        intents[actor.id] = v7Reach(actor, source.spatial)
          ? { interface: 'gather', args: { target: source.id, quantity: 1 } }
          : { interface: 'navigate', args: { target: source.id, x: 0, y: 0 } };
      } else
        intents[actor.id] = {
          interface: actor.vitals.energy < 38 ? 'rest' : 'wait',
          args: {},
        };
    }
    const result = v7Step(world, intents, continuousRegistry());
    if (result.paused) throw new Error(result.paused);
    if (Object.values(result.outcomes).some((o) => !o.success))
      throw new Error(
        `Offline feasibility action failed: ${JSON.stringify(result.outcomes)}`,
      );
    world = result.world;
    for (const event of world.events)
      if (event.actor && event.interface) {
        actions[event.interface] = (actions[event.interface] ?? 0) + 1;
        if (event.type === 'ate') firstMeals[event.actor] ??= world.tick;
        if (event.type === 'moved' || event.type === 'arrived')
          distance[event.actor] =
            (distance[event.actor] ?? 0) + Number(event.data.distance ?? 0);
      }
    for (const actor of world.actors) {
      minimumSatiety[actor.id] = Math.min(
        minimumSatiety[actor.id] ?? 100,
        actor.vitals.satiety,
      );
      minimumHealth[actor.id] = Math.min(
        minimumHealth[actor.id] ?? 100,
        actor.vitals.health,
      );
    }
  }
  if (world.actors.some((a) => a.vitals.health !== 100))
    throw new Error(
      'Offline long-window baseline survival was not maintained.',
    );
  return {
    version: 7,
    controller: 'isolated-feasibility-oracle',
    purpose:
      'Prove baseline feasibility only; this policy and its routes are excluded from ordinary prompts, calls and discovery evidence.',
    rounds,
    modelCalls: calls,
    configuration: world.config,
    starts: initial.actors.map((a) => ({
      actor: a.id,
      position: a.position,
      nearestObservedFoodDistance: Math.min(
        ...v7Observe(initial, a.id)
          .objects.filter((o) =>
            initial.resources.some(
              (r) => r.id === o.data.resource && r.nutrition > 0,
            ),
          )
          .map((o) => v7Distance(a.position, o.spatial)),
      ),
    })),
    initialFoodUnits: initial.objects
      .filter((o) =>
        initial.resources.some(
          (r) => r.id === o.data.resource && r.nutrition > 0,
        ),
      )
      .reduce((n, o) => n + Number(o.data.stock), 0),
    renewal:
      'Twelve established perennial sources each replenish at most one ripe unit per twelve rounds using declared external daylight and groundwater, only below standing capacity twelve. Harvest and consumption require separate paid actions.',
    metabolicDemand: rounds * 3 * world.config.hunger,
    firstMeals,
    minimumSatiety,
    minimumHealth,
    movementDistance: distance,
    actionDistribution: actions,
    final: world.actors.map((a) => ({
      id: a.id,
      vitals: a.vitals,
      wellbeing: a.wellbeing,
    })),
  };
}

scripts/continuous-source.ts:
import { forestCheckpointRepair } from './forest-checkpoint-repair.js';
import { parseContinuousReviews } from '../apps/simulator/src/continuous-run.js';
import type { V7Review } from '@self-evolving-world/world-core';
import { CONTINUOUS_VISUALS } from '../apps/viewer/src/continuous-visuals.js';
import {
  existsSync,
  readFileSync,
  readdirSync,
  writeFileSync,
  mkdirSync,
} from 'node:fs';
import { resolve, relative, dirname } from 'node:path';
import { spawnSync } from 'node:child_process';
import {
  continuousRegistry,
  v7Install,
  v7Record,
  v7Signature,
} from '@self-evolving-world/world-core';
import type { V7Execution } from '../apps/simulator/src/continuous-run.js';
import {
  continuousAtomic,
  continuousHash,
  continuousRead,
  continuousWorking,
  reconstructContinuousSegment,
  buildContinuousReplay,
} from './continuous-store.js';
import type { V7ReplaySegment } from './continuous-store.js';

export interface ContinuousSourceRevision {
  id: number;
  tick: number;
  sourceHash: string;
  files: Record<string, string>;
  packages: string[];
  reason: string;
  previousWorldHash: string;
  attemptsHash: string;
  validation: { path: string; sha256: string } | null;
}
export function continuousSources(root: string): Record<string, string> {
  const files: Record<string, string> = {};
  const visit = (path: string): void => {
    for (const entry of readdirSync(path, { withFileTypes: true }).sort(
      (a, b) => a.name.localeCompare(b.name, 'en'),
    )) {
      const full = resolve(path, entry.name);
      if (entry.isSymbolicLink())
        throw new Error(
          'Versioned source and assets cannot escape through symlinks.',
        );
      if (entry.isDirectory()) visit(full);
      else if (entry.isFile() && entry.name !== '.DS_Store')
        files[relative(root, full)] = /\.(ts|css|svg|json|html|md|txt)$/.test(
          entry.name,
        )
          ? readFileSync(full, 'utf8')
          : `base64:${readFileSync(full).toString('base64')}`;
    }
  };
  for (const path of [
    'packages/world-core/src',
    'apps/simulator/src',
    'apps/viewer/src',
    'packages/world-core/test',
    'apps/simulator/test',
    'apps/viewer/test',
    'apps/viewer/e2e',
  ])
    visit(resolve(root, path));
  if (existsSync(resolve(root, 'apps/viewer/public')))
    visit(resolve(root, 'apps/viewer/public'));
  for (const file of readdirSync(resolve(root, 'scripts')).filter(
    (p) =>
      (p.startsWith('continuous-') ||
        p.startsWith('forest-') ||
        p.startsWith('open-')) &&
      p.endsWith('.ts'),
  ))
    files[`scripts/${file}`] = readFileSync(
      resolve(root, 'scripts', file),
      'utf8',
    );
  for (const path of [
    'package.json',
    'pnpm-lock.yaml',
    'apps/viewer/index.html',
    'apps/viewer/classic.html',
    'apps/viewer/observatory.html',
    'apps/viewer/forest-lab.html',
    'apps/viewer/vite.config.ts',
    'packages/world-core/package.json',
    'apps/simulator/package.json',
    'apps/viewer/package.json',
  ])
    files[path] = readFileSync(resolve(root, path), 'utf8');
  return files;
}
/** Runtime identity excludes acceptance tooling/tests while retained snapshots keep their original full hashes. */
export function continuousRuntimeSources(
  files: Record<string, string>,
): Record<string, string> {
  return Object.fromEntries(
    Object.entries(files).flatMap(([path, value]) => {
      if (
        path.startsWith('packages/world-core/src/') ||
        path.startsWith('apps/simulator/src/') ||
        path.startsWith('apps/viewer/src/') ||
        path.startsWith('apps/viewer/public/') ||
        /^scripts\/continuous-(cli|store|window)\.ts$/.test(path)
      )
        return [[path, value]];
      if (path.endsWith('package.json')) {
        const p = JSON.parse(value) as {
          dependencies?: unknown;
          optionalDependencies?: unknown;
          engines?: unknown;
        };
        return [
          [
            path,
            JSON.stringify({
              dependencies: p.dependencies,
              optionalDependencies: p.optionalDependencies,
              engines: p.engines,
            }),
          ],
        ];
      }
      return [];
    }),
  );
}
export function continuousRuntimeHash(files: Record<string, string>): string {
  return continuousHash(continuousRuntimeSources(files));
}
export function currentContinuousRuntimeMatches(
  root: string,
  id: string,
): boolean {
  const revision = continuousHistory(root, id).at(-1);
  if (!revision) return false;
  const retained = continuousRead<Record<string, string>>(
    resolve(
      root,
      'experiment',
      id,
      'sources',
      `revision-${String(revision.id)}.json`,
    ),
  );
  if (continuousHash(retained) !== revision.sourceHash)
    throw new Error('Retained runtime source integrity failed.');
  return (
    continuousRuntimeHash(retained) ===
    continuousRuntimeHash(continuousSources(root))
  );
}
export function continuousHistory(
  root: string,
  id: string,
): ContinuousSourceRevision[] {
  return continuousRead<ContinuousSourceRevision[]>(
    resolve(root, 'experiment', id, 'source-history.json'),
  );
}
export function saveContinuousSource(
  root: string,
  id: string,
  state: V7Execution,
  reason: string,
  validation: ContinuousSourceRevision['validation'] = null,
): void {
  const directory = resolve(root, 'experiment', id),
    path = resolve(directory, 'source-history.json');
  const history = existsSync(path) ? continuousHistory(root, id) : [],
    files = continuousSources(root),
    number = history.length + 1;
  const snapshot = `sources/revision-${String(number)}.json`;
  mkdirSync(dirname(resolve(directory, snapshot)), { recursive: true });
  writeFileSync(resolve(directory, snapshot), JSON.stringify(files) + '\n', {
    flag: 'wx',
  });
  history.push({
    id: number,
    tick: state.world.tick,
    sourceHash: continuousHash(files),
    files: Object.fromEntries(
      Object.entries(files).map(([p, s]) => [p, continuousHash(s)]),
    ),
    packages: state.world.revisions,
    reason,
    previousWorldHash: continuousHash(state.world),
    attemptsHash: continuousHash(state.attempts),
    validation,
  });
  continuousAtomic(path, history);
}
export function captureContinuousBaseline(
  root: string,
  id: string,
  state: V7Execution,
): void {
  if (
    state.phase !== 'development' ||
    !state.barrier ||
    !currentContinuousRuntimeMatches(root, id)
  )
    return;
  const path = resolve(
      continuousWorking(root, id),
      `${state.barrier.id}-baseline.json`,
    ),
    baseline = {
      world: continuousHash(state.world),
      attempts: continuousHash(state.attempts),
      barrier: continuousHash({ ...state.barrier, developmentAttempt: null }),
      history: continuousHash(continuousHistory(root, id)),
      source: continuousHash(continuousSources(root)),
    };
  if (existsSync(path)) {
    if (v7Signature(continuousRead(path)) !== v7Signature(baseline))
      throw new Error('Development baseline changed.');
  } else continuousAtomic(path, baseline);
}
/** Manifest-declared source changes, full tests and exact old-prefix replay replace the old five-file allowlist. */
export function validateContinuousDevelopment(
  root: string,
  id: string,
  state: V7Execution,
  input: unknown,
): {
  world: V7Execution['world'];
  packages: string[];
  assignments: Record<string, string>;
  reviews: V7Review[];
  review: string;
  validation: ContinuousSourceRevision['validation'];
} {
  const declaration = v7Record(input),
    packages = declaration.packages,
    paths = declaration.paths,
    assignments = v7Record(declaration.assignments);
  if (
    !state.barrier ||
    !Array.isArray(packages) ||
    packages.some((p) => typeof p !== 'string') ||
    !Array.isArray(paths) ||
    paths.some((p) => typeof p !== 'string') ||
    typeof declaration.review !== 'string' ||
    declaration.review.length < 40
  )
    throw new Error(
      'Development requires versioned packages, all changed source paths, requester assignments and a substantive implementation review.',
    );
  const baseline = continuousRead<{
    world: string;
    attempts: string;
    barrier: string;
    history: string;
  }>(resolve(continuousWorking(root, id), `${state.barrier.id}-baseline.json`));
  if (
    baseline.world !== continuousHash(state.world) ||
    baseline.attempts !== continuousHash(state.attempts) ||
    baseline.barrier !==
      continuousHash({ ...state.barrier, developmentAttempt: null }) ||
    baseline.history !== continuousHash(continuousHistory(root, id))
  )
    throw new Error(
      'Saved world, calls or development barrier changed during development.',
    );
  const reviews = state.barrier.reviews.length
    ? state.barrier.reviews
    : parseContinuousReviews(
        JSON.stringify({ reviews: declaration.reviews }),
        state.barrier,
        state.world,
      );
  const previous = continuousHistory(root, id).at(-1);
  if (!previous) throw new Error('Missing retained source baseline.');
  const current = continuousSources(root);
  const beforeRuntime = continuousRuntimeSources(
    continuousRead<Record<string, string>>(
      resolve(
        root,
        'experiment',
        id,
        'sources',
        `revision-${String(previous.id)}.json`,
      ),
    ),
  );
  const afterRuntime = continuousRuntimeSources(current);
  const changed = [
    ...new Set([...Object.keys(beforeRuntime), ...Object.keys(afterRuntime)]),
  ]
    .filter((p) => beforeRuntime[p] !== afterRuntime[p])
    .sort();
  const declaredRuntime = (paths as string[])
    .filter((p) => p in beforeRuntime || p in afterRuntime)
    .sort();
  if (v7Signature(changed) !== v7Signature(declaredRuntime))
    throw new Error(
      `Declared runtime source paths must match actual changes: ${changed.join(', ')}`,
    );
  // These enforce experiment identity, authorization and exactly-once budgets rather than world design.
  const protectedPaths =
    /(^scripts\/continuous-|continuous-policy\.ts$|continuous-(run|provider|input)\.ts$|packages\/world-core\/src\/world\.ts$|chatgpt-auth\.ts$|responses\.ts$|package\.json$|pnpm-lock\.yaml$)/;
  if (
    changed.some(
      (p) =>
        !current[p] ||
        (protectedPaths.test(p) &&
          !forestCheckpointRepair(
            p,
            previous.files[p] ?? '',
            continuousHash(current[p]),
            declaration.compatibilityRepair,
          )),
    )
  )
    throw new Error(
      'The run policy, controller, transport, source verifier and historical foundation require a separate run version. Source versions cannot be deleted.',
    );
  const directory = resolve(root, 'experiment', id),
    attempt = state.barrier.developmentAttempt;
  const log = `development/${String(attempt)}-validation.txt`;
  mkdirSync(dirname(resolve(directory, log)), { recursive: true });
  const commands = [['typecheck'], ['architecture:check'], ['test'], ['build']];
  let output = '';
  for (const args of commands) {
    const run = spawnSync('pnpm', args, {
      cwd: root,
      encoding: 'utf8',
      maxBuffer: 32_000_000,
    });
    output += `$ pnpm ${args.join(' ')}\n${run.stdout}${run.stderr}\n`;
    writeFileSync(resolve(directory, log), output);
    if (run.status !== 0)
      throw new Error(
        `Versioned development validation failed: pnpm ${args.join(' ')}`,
      );
  }
  const initial = continuousRead<V7Execution['world']>(
      resolve(directory, 'initial.json'),
    ),
    index = buildContinuousReplay(root, id, initial, state);
  for (const part of index.segments)
    reconstructContinuousSegment(
      continuousRead<V7ReplaySegment>(resolve(directory, part.path)),
    );
  output +=
    'Every saved round reconstructed with identical world and event hashes.\n';
  writeFileSync(resolve(directory, log), output);
  let world = state.world;
  const registry = continuousRegistry(state.world);
  for (const key of packages as string[]) {
    const pkg = registry.packages.find(
      (p) => `${p.id}@${String(p.version)}` === key,
    );
    if (
      !pkg ||
      !pkg.visualComponents.every(
        (component) => typeof CONTINUOUS_VISUALS[component] === 'function',
      )
    )
      throw new Error('Package visual implementation is absent.');
    world = v7Install(world, registry, key);
  }
  const assigned: Record<string, string> = {};
  for (const review of reviews.filter((r) => r.decision === 'develop')) {
    const ability = assignments[review.actor];
    if (
      typeof ability !== 'string' ||
      !world.abilities.some(
        (a) =>
          a.id === ability &&
          (a.learning === review.learning ||
            (state.world.actors
              .find((actor) => actor.id === review.actor)
              ?.mastered.includes(a.id) &&
              state.world.abilities.some(
                (old) => old.id === a.id && old.learning === a.learning,
              ))),
      )
    )
      throw new Error(
        'Every development requester needs an implemented interface with the reviewed learning duration.',
      );
    assigned[review.actor] = ability;
  }
  return {
    world,
    packages: packages as string[],
    assignments: assigned,
    reviews,
    review: declaration.review,
    validation: {
      path: log,
      sha256: continuousHash(readFileSync(resolve(directory, log), 'utf8')),
    },
  };
}

