import { readFileSync } from 'node:fs';
import { expect, it } from 'vitest';
import {
  continuousRegistry,
  v7IndexedClear,
  v7SegmentClear,
  v7Step,
  v7Work,
} from '@self-evolving-world/world-core';
import type { V7Spatial } from '@self-evolving-world/world-core';
import type { V7Execution } from '../apps/simulator/src/continuous-run.js';

it('matches exact collision tests across rotated walls, circles and distant obstacles', () => {
  const obstacles: V7Spatial[] = Array.from({ length: 30 }, (_, i) => ({
    x: (i * 7) % 25,
    y: (i * 11) % 19,
    angle: i * 0.31,
    shape:
      i % 2
        ? { kind: 'circle', radius: 0.3 + (i % 4) * 0.1 }
        : { kind: 'rectangle', width: 0.4, height: 3 },
    solid: true,
    interaction: 0,
    entrances: [],
  }));
  const indexed = v7IndexedClear(obstacles, 0.22, v7Work(5_000_000));
  for (let i = 0; i < 250; i++) {
    const from = { x: ((i * 3.17) % 27) - 1, y: ((i * 4.31) % 21) - 1 };
    const to = { x: ((i * 7.13) % 27) - 1, y: ((i * 8.27) % 21) - 1 };
    expect(indexed(from, to)).toBe(v7SegmentClear(from, to, 0.22, obstacles));
  }
});

it('executes the retained ex8 round-166 intents within the original computation budget without inference or a new strategy', () => {
  const saved = JSON.parse(
    readFileSync(
      'experiment/ex8/technical-pauses/round-166/execution.json',
      'utf8',
    ),
  ) as V7Execution;
  if (!saved.barrier) throw new Error('Missing retained technical barrier');
  expect(saved.world.config.computation.workPerRound).toBe(2_000_000);
  const result = v7Step(
    saved.world,
    saved.barrier.actions,
    continuousRegistry(),
    saved.cursors,
    saved.barrier.reviews,
  );
  expect(result.paused).toBeNull();
  expect(result.world.tick).toBe(167);
  expect(result.world.config).toEqual(saved.world.config);
  expect(result.outcomes.lin?.reason).toContain('No route');
  expect(result.outcomes.sol?.reason).toContain('No route');
  expect(result.outcomes.moss?.success).toBe(true);
});

scripts/forest-preflight.ts:
import {
  v7Step,
  v7Registry,
  V7_PACKAGES,
  v7Install,
  v7Observe,
  v7Reach,
  v7Distance,
  v7Clone,
} from '@self-evolving-world/world-core';
import type { V7Action } from '@self-evolving-world/world-core';
import { initialForestWorld } from '../apps/simulator/src/forest-scenario.js';
import { forestFixturePackage } from '../packages/world-core/test/fixtures/forest-extension.js';

/** Offline viability calculation only. This controller and its fixture ability never enter real inputs. */
export function forestPreflight(rounds = 200, respawn = false) {
  const registry = v7Registry([...V7_PACKAGES, forestFixturePackage]);
  let world = v7Install(
    initialForestWorld(),
    registry,
    'isolated-forest-room@1',
  );
  if (respawn) {
    const damaged = v7Clone(world);
    damaged.actors.forEach((a) => {
      a.vitals.health = 1;
      a.vitals.satiety = 0;
    });
    damaged.objects
      .filter((o) => o.id.startsWith('start-') && o.data.resource === 'berry')
      .forEach((o) => {
        o.data.stock = 0;
      });
    const death = v7Step(
      damaged,
      Object.fromEntries(
        damaged.actors.map((a) => [a.id, { interface: 'wait', args: {} }]),
      ),
      registry,
    );
    if (death.paused) throw new Error(death.paused);
    world = death.world;
    if (
      world.actors.some((a) => a.life?.deaths !== 1) ||
      world.objects.some(
        (o) =>
          o.id.startsWith('start-') &&
          o.data.resource === 'berry' &&
          o.data.stock !== 0,
      )
    )
      throw new Error(
        'Respawn calibration changed life counts or refreshed depleted food.',
      );
  }
  const initial = world,
    actions: Record<string, number> = {},
    minima: Record<string, { health: number; satiety: number }> = {},
    distance: Record<string, number> = {};
  for (let tick = 0; tick < rounds; tick++) {
    const intents: Record<string, V7Action> = {};
    for (const actor of world.actors) {
      const observation = v7Observe(world, actor.id);
      const owned = world.stacks.find(
        (s) =>
          s.owner === actor.id &&
          world.resources.some(
            (r) => r.id === s.resource && r.nutrition > 0 && r.toxicity === 0,
          ),
      );
      if (tick === 0)
        intents[actor.id] = {
          interface: 'learn',
          args: { ability: 'fixture-build' },
        };
      else if (actor.learning)
        intents[actor.id] = { interface: 'wait', args: {} };
      else if (actor.vitals.energy < 5)
        intents[actor.id] = { interface: 'rest', args: {} };
      else if (actor.vitals.satiety < 72 && owned)
        intents[actor.id] = {
          interface: 'eat',
          args: { target: owned.id, quantity: 1 },
        };
      else if (actor.vitals.satiety < 72) {
        const sources = observation.objects
          .filter(
            (o) =>
              Number(o.data.stock) > 0 &&
              world.resources.some(
                (r) =>
                  r.id === o.data.resource &&
                  r.nutrition > 0 &&
                  r.toxicity === 0,
              ),
          )
          .sort(
            (a, b) =>
              v7Distance(actor.position, a.spatial) -
              v7Distance(actor.position, b.spatial),
          );
        const source = sources[0];
        if (!source)
          throw new Error(
            `No safe observed food during isolated feasibility: ${actor.id} at ${String(tick)}.`,
          );
        intents[actor.id] = v7Reach(actor, source.spatial)
          ? { interface: 'gather', args: { target: source.id, quantity: 1 } }
          : { interface: 'navigate', args: { target: source.id, x: 0, y: 0 } };
      } else
        intents[actor.id] = {
          interface: actor.vitals.energy < 38 ? 'rest' : 'wait',
          args: {},
        };
    }
    const result = v7Step(world, intents, registry);
    if (result.paused || Object.values(result.outcomes).some((o) => !o.success))
      throw new Error(
        `Forest feasibility execution: ${JSON.stringify(result.outcomes)} ${result.paused ?? ''}`,
      );
    world = result.world;
    for (const event of world.events)
      if (event.interface && event.actor) {
        actions[event.interface] = (actions[event.interface] ?? 0) + 1;
        distance[event.actor] =
          (distance[event.actor] ?? 0) + Number(event.data.distance ?? 0);
      }
    for (const actor of world.actors) {
      const old = minima[actor.id] ?? { health: 100, satiety: 100 };
      minima[actor.id] = {
        health: Math.min(old.health, actor.vitals.health),
        satiety: Math.min(old.satiety, actor.vitals.satiety),
      };
      if (
        (actor.life?.deaths ?? 0) > (respawn ? 1 : 0) ||
        actor.vitals.health <= 0
      )
        throw new Error(
          'The suitable-season baseline did not preserve its initial life.',
        );
    }
  }
  return {
    version: 1,
    controller: 'isolated-forest-feasibility',
    modelCalls: 0,
    respawn,
    rounds,
    purpose:
      'Demonstrate complete travel/gather/eat/rest and actual individual study costs in suitable conditions. This is not a winter survival claim or an autonomous policy.',
    configuration: initial.config,
    initialResources: initial.resources.length,
    initialObjects: initial.objects.length,
    learning:
      'All three actors spend three real rounds learning an isolated interface, never executing its authored activity. The package and policy are excluded from real genesis and prompts.',
    minima,
    movementDistance: distance,
    actionDistribution: actions,
    spareRounds: (actions.wait ?? 0) - 6,
    final: world.actors.map((a) => ({
      actor: a.id,
      vitals: a.vitals,
      lives: a.life,
    })),
  };
}

scripts/open-analysis.ts:
import { continuousRegistry } from '@self-evolving-world/world-core';
import type { V7World } from '@self-evolving-world/world-core';
import type {
  V7Execution,
  V7RoundRecord,
} from '../apps/simulator/src/continuous-run.js';

export const OPEN_OBJECTIVE =
  'Observe early cumulative open development in one fresh three-actor world for a target 1600 rounds under fixed policy and 650/60/20 attempt budgets. Grounded questions, dependent capabilities and non-survival experiences are observations, not mandatory inventions or evidence of inevitable civilization.';
export function measureOpen(
  state: V7Execution,
  frames: V7World[],
  rounds: V7RoundRecord[],
) {
  const world = state.world,
    events = rounds.flatMap((r) => r.events);
  const packages = continuousRegistry(world).packages.filter((p) =>
    world.revisions.includes(`${p.id}@${String(p.version)}`),
  );
  return {
    inheritSkills: world.config.development?.inheritSkills,
    scope: world.config.development?.scope,
    authoredBaseline: world.config.development?.baseline,
    initialRevisions: frames[0]?.revisions,
    implementations: packages
      .filter((p) => p.scope)
      .map((p) => ({
        package: `${p.id}@${String(p.version)}`,
        scope: p.scope,
        reuse: p.reuse ?? null,
        abilities: p.abilities.map((a) => ({
          id: a.id,
          equivalence: a.equivalence,
          dependencies: a.dependencies ?? null,
        })),
      })),
    projectUpdates: rounds.flatMap((r) =>
      Object.entries(r.memory).flatMap(([actor, m]) =>
        (m.projects ?? []).map((p) => ({ tick: r.tick, actor, project: p })),
      ),
    ),
    finalPersonalRecords: world.actors.map((a) => ({
      actor: a.id,
      projects: a.memory.projects ?? {},
      knowledge: a.memory.knowledge ?? {},
      relationships: a.relationships,
    })),
    confirmedInformation: events.filter(
      (e) => e.type === 'information-confirmed',
    ),
    trials: events.filter(
      (e) => e.type === 'trial-result' || e.type === 'trial-material-consumed',
    ),
    practice: events.filter((e) => e.type === 'practice-confirmed'),
    exchanges: events.filter(
      (e) => e.type === 'finding-offered' || e.type === 'finding-accepted',
    ),
    processes: events.filter((e) =>
      ['process-progress', 'process-completed', 'process-stopped'].includes(
        e.type,
      ),
    ),
    ecology: events.filter((e) =>
      [
        'seed-dispersed',
        'plant-established',
        'animal-fed',
        'animal-born',
        'animal-injured',
        'local-hazard',
      ].includes(e.type),
    ),
    outstandingProcesses: world.processes,
    materialProvenance: world.stacks
      .filter((s) => s.processing)
      .map((s) => ({
        id: s.id,
        resource: s.resource,
        quantity: s.quantity,
        owner: s.owner,
        origin: s.origin,
        processing: s.processing,
      })),
    context: state.attempts.map((a) => ({
      id: a.id,
      role: a.role,
      tick: a.tick,
      reason: a.reason,
      status: a.status,
      inputUtf8Bytes: a.contextBytes ?? null,
      inputCodeUnits: a.contextCodeUnits ?? null,
      inputTokens: a.usage?.inputTokens ?? null,
      outputTokens: a.usage?.outputTokens ?? null,
      elapsedMs: a.elapsedMs,
    })),
    interpretation:
      'Project completion and benefit fields are actor claims. Corroborate them with actual events, material provenance and subsequent execution. Fixtures and historical implementation reuse are not independent emergent discoveries. Context byte measurements cover input content; reported provider tokens include actual model accounting. Internal development usage is unknown.',
  };
}

scripts/open-preflight.ts:
import {
  continuousRegistry,
  v7Step,
  v7Observe,
  v7Reach,
  v7Distance,
  forestRoute,
  v7Work,
  v7Approach,
  v7Clone,
} from '@self-evolving-world/world-core';
import type { V7Action } from '@self-evolving-world/world-core';
import { initialOpenWorld } from '../apps/simulator/src/open-scenario.js';

/** Isolated feasibility oracle. This file and its policy are never sent to the ordinary model. */
export function openPreflight(rounds = 1600) {
  let world = initialOpenWorld();
  const registry = continuousRegistry(world),
    initial = world;
  const actions: Record<string, number> = {},
    failures: Record<string, number> = {},
    minima: Record<string, { health: number; satiety: number }> = {},
    firstFood: Record<string, number> = {};
  const food = (id: unknown) =>
    world.resources.find(
      (r) => r.id === id && r.nutrition > 0 && r.toxicity === 0,
    );
  const blocked = new Map<string, Set<string>>();
  for (let tick = 0; tick < rounds; tick++) {
    // This omniscient feasibility oracle is deliberately separate from private formal observations.
    world = v7Clone(world);
    for (const a of world.actors) {
      a.memory.objects = world.objects.map((object) => ({
        object: v7Clone(object),
        seenAt: world.tick,
      }));
      a.memory.cells = world.terrain.flatMap((row, y) =>
        Array.from(
          { length: row.length },
          (_, x) => `${String(x)},${String(y)}`,
        ),
      );
    }
    const intents: Record<string, V7Action> = {};
    for (const actor of world.actors) {
      const o = v7Observe(world, actor.id);
      const owned = world.stacks.find(
        (s) => s.owner === actor.id && !s.reservedFor && food(s.resource),
      );
      const available = [
        ...o.objects,
        ...actor.memory.objects
          .filter((m) => !o.objects.some((x) => x.id === m.object.id))
          .map((m) => m.object),
      ]
        .filter(
          (x) =>
            food(x.data.resource) &&
            Number(x.data.stock) > 0 &&
            !blocked.get(actor.id)?.has(x.id) &&
            initial.actors
              .slice()
              .sort(
                (a, b) =>
                  v7Distance(a.position, x.spatial) -
                  v7Distance(b.position, x.spatial),
              )[0]?.id === actor.id,
        )
        .sort(
          (a, b) =>
            v7Distance(actor.position, a.spatial) -
            v7Distance(actor.position, b.spatial),
        );
      const source = available[0];
      const visibleSource =
        source ??
        world.objects
          .filter(
            (x) =>
              food(x.data.resource) &&
              Number(x.data.stock) > 0 &&
              !blocked.get(actor.id)?.has(x.id) &&
              initial.actors
                .slice()
                .sort(
                  (a, b) =>
                    v7Distance(a.position, x.spatial) -
                    v7Distance(b.position, x.spatial),
                )[0]?.id === actor.id,
          )
          .sort(
            (a, b) =>
              v7Distance(actor.position, a.spatial) -
              v7Distance(actor.position, b.spatial),
          )[0];
      if (actor.learning) intents[actor.id] = { interface: 'wait', args: {} };
      else if (actor.vitals.satiety < 78 && owned)
        intents[actor.id] = {
          interface: 'eat',
          args: { target: owned.id, quantity: 1 },
        };
      else if (actor.vitals.energy < 8)
        intents[actor.id] = { interface: 'rest', args: {} };
      else if (actor.vitals.satiety < 78 && visibleSource) {
        if (v7Reach(actor, visibleSource.spatial))
          intents[actor.id] = {
            interface: 'gather',
            args: { target: visibleSource.id, quantity: 1 },
          };
        else {
          // The isolated oracle may search real interaction points; it still pays continuous movement and collision costs.
          const center = visibleSource.spatial;
          const points = [
            v7Approach(actor, center),
            ...Array.from({ length: 16 }, (_, i) => ({
              x: center.x + Math.cos((i * Math.PI) / 8) * 0.8,
              y: center.y + Math.sin((i * Math.PI) / 8) * 0.8,
            })),
          ];
          const point = points.find(
            (p) =>
              forestRoute(
                world,
                actor,
                p,
                v7Work(world.config.computation.workPerRound),
              ).path.length > 0,
          );
          if (point)
            intents[actor.id] = {
              interface: 'navigate',
              args: { target: '', x: point.x, y: point.y },
            };
          else {
            const set = blocked.get(actor.id) ?? new Set<string>();
            set.add(visibleSource.id);
            blocked.set(actor.id, set);
            intents[actor.id] = { interface: 'wait', args: {} };
          }
        }
      } else
        intents[actor.id] = {
          interface: actor.vitals.energy < 35 ? 'rest' : 'wait',
          args: {},
        };
    }
    const result = v7Step(world, intents, registry);
    if (result.paused) throw new Error(result.paused);
    world = result.world;
    for (const actor of world.actors) {
      const action = intents[actor.id],
        outcome = result.outcomes[actor.id];
      actions[action?.interface ?? 'none'] =
        (actions[action?.interface ?? 'none'] ?? 0) + 1;
      if (outcome && !outcome.success) {
        failures[outcome.reason] = (failures[outcome.reason] ?? 0) + 1;
        if (typeof action?.args.target === 'string') {
          const set = blocked.get(actor.id) ?? new Set<string>();
          set.add(action.args.target);
          blocked.set(actor.id, set);
        }
      }
      if (
        action?.interface === 'gather' &&
        outcome?.success &&
        firstFood[actor.id] === undefined
      )
        firstFood[actor.id] = world.tick;
      const prior = minima[actor.id] ?? { health: 100, satiety: 100 };
      minima[actor.id] = {
        health: Math.min(prior.health, actor.vitals.health),
        satiety: Math.min(prior.satiety, actor.vitals.satiety),
      };
      if ((actor.life?.deaths ?? 0) > 0)
        throw new Error(
          `Isolated baseline lost a life: ${actor.id} at ${String(world.tick)}; ${JSON.stringify({ minima, actions, failures })}`,
        );
    }
    if (tick % 80 === 79) blocked.clear();
  }
  const spare = actions.wait ?? 0;
  if (spare < rounds * 3 * 0.15)
    throw new Error('Baseline leaves less than 15% optional activity time.');
  return {
    version: 1,
    controller: 'isolated-fresh-development-feasibility',
    modelCalls: 0,
    rounds,
    seed: initial.config.seed,
    configuration: initial.config,
    firstFoodRound: firstFood,
    initialSafeNutrition: initial.objects.reduce(
      (n, x) =>
        n + Number(x.data.stock ?? 0) * (food(x.data.resource)?.nutrition ?? 0),
      0,
    ),
    nearestFoodDistances: initial.actors.map((a) => ({
      actor: a.id,
      distance: Math.min(
        ...initial.objects
          .filter((x) => food(x.data.resource))
          .map((x) => v7Distance(a.position, x.spatial)),
      ),
    })),
    minima,
    actions,
    failures,
    optionalRounds: spare,
    optionalShare: spare / (rounds * 3),
    final: world.actors.map((a) => ({
      id: a.id,
      vitals: a.vitals,
      lives: a.life,
      mental: a.experience?.mental,
    })),
    limitation:
      'Authored offline feasibility only; no autonomous discovery or causal guarantee. Oracle uses actual safe definitions, which are excluded from ordinary inputs.',
  };
}

